export default [{"id":653,"question":"هل ثبت عن رسول الله ﷺ أنه صام عشر ذي الحجة؟","title":"ما حكم صيام عشر ذي الحجة؟","answer":"الجواب: ما ثبت، يروى عنها بسند فيه اضطراب، عائشة تقول: ما كان يصومها. ويُروى عن حفصة أنه كان يصومها ولكن في سنده بعض الاضطراب، ولكن صومها سُنة؛ لقوله ﷺ: ما من أيام العمل الصالح فيها خير وأحب إلى الله من هذه الأيام العشر رواه البخاري في الصحيح، وهكذا روى أحمد بإسناد جيد: ما من أيام أعظم عند الله ولا أحب إليه العمل فيهن من هذه الأيام العشر؛ فأكثروا فيهن من التهليل والتحميد والتكبير، تقول عائشة رضي الله عنها: ما أعلمها صامها، ويُروى عن حفصة أنه كان يصومها، لكن بسند فيه بعض الاضطراب. (دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6684/ما-حكم-صيام-عشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/maram222 - 03 - .mp3","categories":["صيام التطوع"]},{"id":794,"question":"شخصٌ صام يوم عاشوراء، ولم يصم يومًا قبله أو يومًا بعده، فما الحكم جزاكم الله خيرًا؟","title":"حكم صيام عاشوراء دون صيام قبله أو بعده","answer":"الجواب: المشهور عند العلماء: أنه مكروهٌ؛ لأنَّ النبي  قال في الأخير: لئن عشتُ لأصومنَّ التاسع، وكذلك بعدما نهي عن مُوافقة أهل الكتاب، كان أولًا يُحب مُوافقتهم فيما لم يُنْهَ عنه، وكان يصوم عاشوراء فقط، ثم أمره الله بمُخالفة المشركين، وعدم مُوافقتهم، فقال: لئن عِشْتُ إلى قابلٍ لأصومَنَّ التاسع، فلم يُدْرِك ذلك، وقال ابنُ عباسٍ -راوي الحديث: \"يصوم التاسع والعاشر\".\nوروى أحمد وغيرُه عن النبي ﷺ أنه قال: صوموا يومًا قبله ويومًا بعده، وفي لفظٍ آخر: صوموا يومًا قبله أو يومًا بعده، لكن في إسناده ضعفٌ؛ لأنه من رواية محمد بن أبي ليلى، وهو يضعف في الحديث، لكن له شواهد في المعنى.\nفالسنة عند أهل العلم أن يُصام قبله يومٌ، أو بعده يومٌ، أو يُصام ما قبله وما بعده -ثلاثة أيام- يكون للجميع، هذا هو السنة، حتى لا يُوافق أهلَ الكتاب.","link":"https://binbaz.org.sa/fatwas/20781/حكم-صيام-عاشوراء-دون-صيام-قبله-او-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0612ما حكم صيام عاشوراء فقط دون صيام يوم قبله أو يوم بعده؟ ابن باز فتاوى المحاضرات.mp3","categories":["صيام التطوع"]},{"id":1216,"question":"قال ﷺ: مَن صام ثلاثة أيام من كل شهرٍ فقد صام الدهرَ كله،  هل يقصد بالثلاثة أيام الأيام البيض أو أي ثلاثة أيام؟","title":"هل صوم ثلاثة أيام كل شهر يُقصد به البِيض؟","answer":"الجواب:\nالشيخ: عامٌّ، يعمّ الأيام كلها، ثلاثة أيام من كل شهر، سواء من أوله، أو من آخره، أو من وسطه؛ لأنَّ الأحاديث الصَّحيحة كلها ليس فيها البيض، فيها صوم ثلاثة أيام، والنبي ﷺ أوصى أبا هريرة وأوصى أبا الدَّرداء بصيام ثلاثة أيام من كل شهرٍ، ولم يقل لهما: البيض، وهكذا قال لعبدالله بن عمرو: صم من الشهر ثلاثة أيام.\nلكن إذا صام البيض فهو أفضل، كما جاء في حديث أبي ذرٍّ: يصوم الثالث عشر والرابع عشر والخامس عشر، إذا صام البيض فذلك أفضل، وإلا فيكفي أن يصوم من الشهر، سواء كان من أوله، أو من وسطه، أو من آخره، والحمد لله، سواء متفرقة أو مجتمعة أيضًا، سواء جمعها وتابعها أو فرَّقها.","link":"https://binbaz.org.sa/fatwas/21272/هل-صوم-ثلاثة-ايام-كل-شهر-يقصد-به-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1122قال عليه الصلاة والسلام من صام ثلاثة أيام من كل شهر فقد صام الشهر كله هل هي البيض.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1406,"question":"صيام الأبد نهي تحريم أم كراهة؟","title":"ما حكم صيام الدهر؟","answer":"الجواب:\nالصواب تحريمه لا صَامَ مَن صَامَ الأبَدَ الرسول ﷺ نهى عنه.","link":"https://binbaz.org.sa/fatwas/21499/ما-حكم-صيام-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النهي عن صيام الدهر للتحريم أم للكراهة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1589,"question":"زوجتي عندي تصوم الخميس والإثنين، وتسأل هل يجوز أن أصوم قبل دخول الشهر؟","title":"حكم صيام آخر شعبان لمن له عادة صوم؟","answer":"الجواب:\nتصوم؛ لأن هذا عادة لها، فالذي له عادة يصومها، أما مَن لم يكن له عادة فلا يصم، لا يصم يوم الثلاثين ولا تسعة وعشرين، لا يصم بعد نصف شعبان، أما مَن له عادة فلا بأس، كمَن يصوم يومًا ويُفْطر يومًا، أو يصوم الإثنين والخميس، فله أن يصوم، قال النبيُّ ﷺ: إلا رجل كان يصوم صومًا فليصُمْه.\nس: يشمل ذلك يوم الشك؟\nج: كله يوم الشك.","link":"https://binbaz.org.sa/fatwas/21692/حكم-صيام-اخر-شعبان-لمن-له-عادة-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقدم شهر رمضان بيوم أو يومين لمن كان له عادة الصوم.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1691,"question":"رجلٌ اعتاد صيامَ الاثنين والخميس، فإذا دُعِيَ يوم الاثنين يعني: وعده شخصٌ وقال له: يوم الاثنين - إن شاء الله - تتغدَّى عندي، فهل الأفضل أن يقول له: أنا اعتدتُ الصيامَ أو يفطر؟","title":"حكم مَن دُعِي لوليمة في يومٍ اعتاد صومه","answer":"الجواب:\nلا، يُجيب الدعوةَ ولا يأكل، يُجيب الدعوةَ، ويعتذر عن الطعام، وإن أفطر فلا بأس، فالنبي ﷺ قال: إذا دُعِيَ أحدُكم فليُجِبْ: فإن كان صائمًا فليدعو، وإن كان مُفْطِرًا فليطعم، إن كان صائمًا يدعو لهم ويقول: سامحوني أنا صائم، وجزاكم الله خيرًا، فيذهب إليهم، ويدعو لهم، وإن أفطر فلا بأس.\nس: مُخَيَّرٌ بين الاثنين؟\nج: نعم مُخَيَّرٌ، وإن كان جبرُهم بالفطر أفضل.\nس: يعني: يكون أميرَ نفسه؟\nج: نعم، لكن يُجيبهم، ويذهب إليهم، ثم يعتذر، أو يُفْطِر، ويأكل معهم.\nس: هل الأفضل أن يعتذر لهم؟\nج: إذا كان يَجْبُرُهم بذلك، ويرى أنَّ المصلحة في إفطاره جَبْرًا لخواطرهم أفطر، وإن لم يكن يضرُّهم، ولا يهمُّهم؛ أفطر أو ما أفطر فيعتذر، يقول: سامحوني أنا صائم، وجئتُ وأجبتُ الدَّعوة، وسامحوني في أن أرجع.","link":"https://binbaz.org.sa/fatwas/21797/حكم-من-دعي-لوليمة-في-يوم-اعتاد-صومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كانت له عادة صيام ودعي لوليمة يوم صيامه هل يجيب أم يعتذر.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":1726,"question":"كذلك بالنسبة للأيام العشر: كثيرٌ من الناس يصومون من أولها إلى اليوم العاشر، فهل هناك دليل يُثبت ذلك؟","title":"ما الدليل على فضل صيام عشر ذي الحجة","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/21833/ما-الدليل-على-فضل-صيام-عشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيام عشر ذي الحجة كاملة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":1857,"question":"حكم المرأة عند سفر زوجها ألا تصوم؟","title":"حكم صيام المرأة حال سفر زوجها دون إذن","answer":"الجواب:\nتصوم.\nس: تصوم ولا تستأذن؟\nج: الرسول ﷺ قال: وزوجها شاهد يعني: حاضر، أما إذا كان غائبًا فلا تحتاج إلى إذنٍ، تصوم تطوُّعًا ولا بأس.","link":"https://binbaz.org.sa/fatwas/21966/حكم-صيام-المراة-حال-سفر-زوجها-دون-اذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قضاء الصيام عند المرأة في سفره.mp3","categories":["صيام التطوع","الحقوق الزوجية"]},{"id":1860,"question":"بعض الأزواج يمنعون زوجاتهم من صيام التطوع؟","title":"حكم منع الزوج زوجته من صيام التطوع","answer":"الجواب:\nلا بأس عليهم، هو محتاج لها، يستمتع بها، فإذا منعها فلا بأس تمتنع.\nس: بعضهم يكون مسافرًا؟\nج: لا، إذا كان مسافرًا فليس له حقّ.\nس: يقول: لصحتك وجمالك وكذا لا تصومي؟\nج: لا، ما له حقّ، إذا سافر لها أن تصوم؛ بنصِّ الحديث.","link":"https://binbaz.org.sa/fatwas/21969/حكم-منع-الزوج-زوجته-من-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم منع الزوج لزوجته من صيام التطوع.mp3","categories":["صيام التطوع","الحقوق الزوجية","قضايا المرأة"]},{"id":1990,"question":"لو صادف يوم عرفة أو عاشوراء يوم الجمعة هل يُصام؟","title":"حكم صوم الجمعة يوم عرفة أو عاشوراء","answer":"الجواب:\nصامه لأجل ما هو الجمعة، صامه لأنه يوم عرفة، ما في بأس.\nس: هل يُستحب له أن يضيف يومًا لصيام يوم عرفة في يوم الجمعة؟\nالشيخ: إذا صام يوم الخميس أفضل مع الجمعة، كالسُّنة يصوم يومًا قبله ولا يومًا بعده، فإذا صام معه الخميس يكون أكمل وأطيب.\nس: كذلك في عاشوراء أحسن الله إليك، لو أضاف يوما آخر...؟\nالشيخ: يوم السبت، وإلا يوم الخميس أحسن.\nس: حتى لا يُفْرِدَه لوحده.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/22106/حكم-صوم-الجمعة-يوم-عرفة-او-عاشوراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صادف يوم عرفة يوم الجمعة أو عاشوراء هل يصام.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2232,"question":"صيام شعبان يكون كاملًا أو نصفه؟","title":"هل السُّنة صومُ شعبان كله أو بعضه؟","answer":"الجواب:\nيصوم أكثره أو كله، فقد كان عليه الصلاة والسلام يصوم أكثره أو كله إلا قليلًا.\nس: والقول بأن يصوم الخمسة عشر الأولى من بداية شعبان؟\nج: لا، يصوم أكثره أو كله، هذه السنة.\nس: إذا تابع الصيامَ من أوله هل له أن يصله برمضان أم يفطر يومًا أو يومين بينهما؟\nج: إن أفطر بينهما حسن، وإلا فله، تقول أم سلمة: \"كان يصومه كله\"، وفي روايةٍ عن عائشة: \"كان يصومه كله\".","link":"https://binbaz.org.sa/fatwas/22355/هل-السنة-صوم-شعبان-كله-او-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيام شهر شعبان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2271,"question":"رجلٌ اعتاد صيامَ ثلاثة أيامٍ من كل شهرٍ -الثلاثة أيام البيض- والثلاثة الأيام هذه سافر، فيقول: هل إذا رجع يصوم ثلاثة أيام في نهاية شهر شعبان؟","title":"حكم الصوم آخر شعبان لمن فاته صوم اعتاده","answer":"الجواب:\nما هو بلازمٍ، لا، هي سنة فات محلُّها، وإذا صامها في بقية الأيام لا بأس، ما هو من أجل رمضان، وإنما صامها من أجل أنه يصوم ثلاثة أيام من كل شهرٍ، فلا بأس ولا حرج، مثلما قال ﷺ: لا تقدموا رمضان بصوم يومٍ أو يومين، إلا أن يكون صومٌ يصومه أحدُكم، فإذا كان يصوم الثلاثة أيام البيض وفاتته وأحبَّ أن يصومها فلا بأس.","link":"https://binbaz.org.sa/fatwas/22394/حكم-الصوم-اخر-شعبان-لمن-فاته-صوم-اعتاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتاد صيامَ ثلاثة أيامٍ من كل شهرٍ وسافر فهل يصوم نهاية شعبان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2496,"question":"قول الرسول ﷺ: أفضل الصيام بعد رمضان شهر الله المحرم يقصد به عاشوراء أو نفس الشهر؟","title":"هل فضلُ صيام المُحَرَّم يُقصد به عاشوراء؟","answer":"الجواب:\nالشهر كله، وإذا ما صامه كله وصام العاشر والتاسع أو العاشر والحادي، كله خير إن شاء الله.","link":"https://binbaz.org.sa/fatwas/22626/هل-فضل-صيام-المحرم-يقصد-به-عاشوراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث أفضل الصيام بعد رمضان شهر الله المحرم.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2638,"question":"يقول من صام يوما في سبيل الله، الذي يصوم في التقاء الصفين؟","title":"ما حكم الصوم في حال الجهاد؟","answer":"الجواب: لا ما ينبغي له الصوم، في الجهاد لا، ما ينبغي؛ لأن النبي ﷺ لما دنا من مكة عام الفتح أمرهم بالإفطار وقال: أفطروا فإن الفِطْر أقوى لكم في جهاد عدوكم فلما بلغه أن بعضهم صام قال: أولئك العصاة، أولئك العصاة وقت الحاجة لا يصوموا؛ لأن الفِطر أقوى، في سبيل الله، يعني في طاعة الله وابتغاء مرضاته، لا رياء ولا سمعة.\nس: والراجح عندكم؟\nالشيخ: هذا أحسن ما قيل في الحديث.\nس: إذا كان في مرابطة؟\nالشيخ: إذا كان في مرابطة أو في وقت لا يضعفه الصيام ما فيه ملاقاة؛ لا بأس، فيه فضل.\nس: يدخل فيه الفرض والنافلة؟\nالشيخ: لا، المراد هنا النافلة.","link":"https://binbaz.org.sa/fatwas/22773/ما-حكم-الصوم-في-حال-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الذي يصوم في الجهاد.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2640,"question":"معنى صيام ثلاثة أيام من كل شهر كصيام الدهر؟","title":"معنى أن ثلاثة أيام كل شهر كصوم الدهر","answer":"الجواب: الحسنة بعشر أمثالها، كل يوم عن عشرة.","link":"https://binbaz.org.sa/fatwas/22775/معنى-ان-ثلاثة-ايام-كل-شهر-كصوم-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى صيام ثلاثة أيام من كل شهر كصيام الدهر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2660,"question":"إذا كان الإنسان يصوم يومًا ويفطر يومًا ووافق يوم الجمعة؟","title":"حكم الجُمعة لمن يصوم يومًا ويفطر يومًا","answer":"الجواب: يصوم يوم الجمعة ويفطر يوم السبت؛ لأنه ما صام لأجل الجمعة، صام لأجل القاعدة: يصوم يومًا ويفطر يومًا. س: إنْ كان عليه قضاء؟ الشيخ: يصوم الجمعة؛ لأنه واجب عليه.","link":"https://binbaz.org.sa/fatwas/22796/حكم-الجمعة-لمن-يصوم-يوما-ويفطر-يوما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يصوم يوما ويفطر يوما ووافق يوم الجمعة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2681,"question":"إذا صام التاسع والعاشر والحادي عشر، ألا يُنهى عن صيام يوم العيد؟","title":"ما الأفضل في الصوم قبل عاشوراء وبعده؟","answer":"الجواب: لا هذا في عاشوراء، يصوم التاسع والعاشر والحادي عشر، عاشوراء، أما ذو الحجة ما فيه إلا التاسع والثامن، يبغى يصوم يصوم مع التاسع الثامن. ويوم العيد ما يُصام بإجماع المسلمين، يوم النحر ما يُصام لا عن فرض ولا عن نفل.  هذا الكلام في عاشوراء: يصوم يومًا قبله أو يومًا بعده، والأفضل التاسع، وإن صام الاثنين العاشر والحادي والتاسع كله طيب.\nس: الأحوط صيام التاسع حتى يتحرى العاشر؟\nالشيخ: ما في بأس التاسع والعاشر أو العاشر والحادي عشر، لكن إذا صام التاسع يكون أفضل لأن الاحتياط فيه أكثر.\nس: قد يكون صادف العاشر؟\nالشيخ: قد يصادف العاشر... ويكون معه العاشر والحادي.\nس:ألا يدل قوله: \"وأمر بصيامه\" على الوجوب؟\nالشيخ: كان هذا في أول الأمر، ثم نسخ الوجوب، قال قوم من أهل العلم: لم يُكتب صيامه، إنما تأكّد قبل صيام رمضان، كان متأكّدًا ثم لما فرض رمضان صار صومه مستحبًّا بغير تأكيد.","link":"https://binbaz.org.sa/fatwas/22819/ما-الافضل-في-الصوم-قبل-عاشوراء-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيام يوم عاشوراء.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2682,"question":"من كان عنده بعض الكبائر هل يصوم يوم عرفة؟","title":"ما حكم التطوعات لمن عنده بعض الكبائر؟","answer":"الجواب: الذي عنده كبائر والذي ما عنده كبائر يستحب له صيام عرفة، كل مسلم يستحب له صيام عرفة؛ يخفف الله فيه من ذنوبه، عمل صالح.\nس: العاصي المصر على معصية؟\nالشيخ: كل مسلم يستحب له التطوعات ولو أنه عاصٍ، العاصي أوْلى الناس بأن يحرص على وجوه الخير؛ لعله يخفف عنه.","link":"https://binbaz.org.sa/fatwas/22820/ما-حكم-التطوعات-لمن-عنده-بعض-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التطوعات لمن كان عنده بعض الكبائر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2685,"question":"ابن عمرو  ألم يتعبه صوم داوود؟","title":"هل صح أن صوم داوود أتعب ابن عمرو؟","answer":"الجواب: عبدالله بن عمرو كان في آخر حياته يشق عليه، وكان يفطر أيامًا ستة ويصوم أيامًا ستة، ويقول: ما أحب أن أخل بشيء فارقت عليه النبي عليه الصلاة والسلام، فإذا عجز سرد الفطر ثم يسرد الصوم، وهذا من اجتهاده  وإلا لو ترك الحمد لله، الأمر واسع.\nس: ما ثبت عنه أنه قال ليتني أطعت وصية رسول الله ﷺ؟\nالشيخ: يمكن: ليتني قبلت رخصة رسول الله. أظنه جاء عنه اجتهادًا منه، ما أحَبَّ أن يخل بشيء فارق عليه النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/22824/هل-صح-ان-صوم-داوود-اتعب-ابن-عمرو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صوم داوود ألم يتعب ابن عمرو.mp3","categories":["صيام التطوع","التاريخ والسيرة"]},{"id":2686,"question":"يوم الإثنين هل له خاصية معينة؟","title":"هل ليوم الإثنين خاصية معينة؟","answer":"الجواب: لا، بس من جهة الصوم، قد يستغله أصحاب المولد وهذا غلط، إنما هذا من جهة الصوم وأنه يصام؛ لأنه يومٌ بُعث فيه وأُنزل عليه فيه ويوم وُلد فيه عليه الصلاة والسلام، فصار فيه فضلان: فضل كونه يوم مولده، وفضل كونه أنزل عليه الوحي فيه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22825/هل-ليوم-الاثنين-خاصية-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ليوم الاثنين خاصية معينة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2687,"question":"صيام النافلة بعد انتصاف الشهر، شهر شعبان؟","title":"ما حكم صوم التطوع بعد انتصاف شعبان؟","answer":"الجواب: إذا ما صام النصف الأول، لا يصوم بعد النصف إذا كان ما صام في النصف الأول.\nس:أي نافلة مطلقًا؟\nالشيخ: الصوم يعني، إلا إذا كان يصوم الإثنين والخميس فيصوم ما في بأس، إذا كان من عادته يصوم الإثنين والخميس ما يخالف.\nس: أو البيض؟\nالشيخ: البيض قبل النصف الأول.\nس: لو أخرها مثلًا؟\nالشيخ: لا، البيض في ثلاثة عشر وأربعة عشر وخمسة عشر هذه البيض.\nس: إذا ما نوى إلا بعد خمسة عشر شعبان؟\nالشيخ: لا يبتدئ؛ للحديث: إذا انتصف شعبان فلا تصوموا.\nس: إذا صام يومًا واحدًا في النصف الأول من شعبان هل يصوم النصف الثاني؟\nالشيخ: ظاهره لا بأس، إذا كان قبله شيء لا بأس أن يستمر، المقصود أن يصوم أكثر شعبان، هذا المقصود أكثر شعبان.","link":"https://binbaz.org.sa/fatwas/22826/ما-حكم-صوم-التطوع-بعد-انتصاف-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيام التطوع بعد انتصاف شهر شعبان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2691,"question":"إذا كان الصائم تطوعًا لأيِّ من الأسباب أفطر؟","title":"حكم الصائم تطوعًا لو عَرَض له سببٌ للفطر","answer":"الجواب: ما في بأس، المتطوع أمير نفسه؛ إذا أفطر لا بأس، دعت حاجة يفطر، الضيف عنده أو حاجة يفطر.\nس: أو يتقوّى بها على بعض أعمال الدنيا؟\nالشيخ: ما في بأس، ما في حرج.","link":"https://binbaz.org.sa/fatwas/22830/حكم-الصاىم-تطوعا-لو-عرض-له-سبب-للفطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيام التطوع والفطر فيه.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":2693,"question":"مَنْ كان عليه قضاء مِنْ رمضان هل يبدأ بالست أم بالقضاء؟","title":"هل يصوم سِتّ شوال مَنْ عليه قضاء؟","answer":"الجواب: يبدأ من القضاء، القضاء أهم.","link":"https://binbaz.org.sa/fatwas/22832/هل-يصوم-ست-شوال-من-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصوم ست شوال من عليه قضاء من رمضان.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":3179,"question":"امرأة جاءتها الدورة في رمضان ثم قضت تلك الأيام ثم أتبعتها ستة من شوال؛ فهل في ذلك أجر؟","title":"حكم قضاء ستِّ شوال بعد انتهاء شوال","answer":"الجواب: صامت في شوال؟\nس: لا؛ لأن شوال انتهى ولم تصم ستة الأيام؟\nالشيخ: إذا انتهى شوال ما عاد الصيام، مضى وقتها. لكن تصوم...، تصوم من كل شهر ثلاثة أيام، أو تصوم الإثنين والخميس من كل شهر، كله خير، فضل الله واسع.","link":"https://binbaz.org.sa/fatwas/23342/حكم-قضاء-ست-شوال-بعد-انتهاء-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/امرأة تصوم قضاء رمضان، ثم تتبعها بست شوال.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4034,"question":"صيام الإثنين فقط من كل أسبوع؟","title":"حكم صيام الإثنين فقط من كل أسبوع","answer":"الجواب: ما في بأس، يصوم الاثنين، أو الخميس، أو يصومهما جميعاً، كله خير.","link":"https://binbaz.org.sa/fatwas/24270/حكم-صيام-الاثنين-فقط-من-كل-اسبوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيام الإثنين فقط من كل أسبوع.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4367,"question":"رجل صام ثم قال: دعاني رجل آخر، وبعد أن دعاني تركت دعوته، نويت أن أجيب دعوته ثم حصل ظرف ثم تركت دعوته، هل صيامي باقٍ؟","title":"حكم من نوى الفطر من صومه ولم يفعل؟","answer":"الجواب: على صيامه حتى يفطر.","link":"https://binbaz.org.sa/fatwas/24644/حكم-من-نوى-الفطر-من-صومه-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصبح صائمًا ثم نوى الفطر، فهل يُفطر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4370,"question":"في آثار رويت عن عمر وعن عائشة وعن أبي طلحة عند الطبراني وعند أبي بكر الفريابي وابن سعد أنهم كانوا يسردون الصوم، وبعضهم كان يسرد الدهر كله، فعلى ماذا تُحمل هذه الروايات؟","title":"علام يُحمل سَرْدُ بعض الصحابة الصوم؟","answer":"الجواب: من يسرد خَفِي عليه الدليل، النبي ﷺ نهى عن الوصال، ونهى عن صوم الدهر، لا صام من صام الأبد ومن فعله من الصحابة فقد خفيت عليه السنة، فالسنة هي الحاكمة على الناس فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ [النساء:59] وإلا إلى زيد وعمرو، فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59].\nس: شهرة مثل هذا الأمر في النهي عن سرد الصوم؟\nج: على كل حال الإنسان يتحرَّى السنة، ولا عليه من زيد وعمرو، يتحرَّى السنة إذا أراد يصوم يومًا ويفطر يومًا، ويصوم الاثنين والخميس، ثلاثة أيام من كل شهر طيب، أما أن يسرد الصوم الدهر كله هذا ما له صوم، النبي ﷺ قال: لا صام ولا أفطر، لا صام من صام الأبد، نهى عن هذا عليه الصلاة والسلام، ولما طلبوا الوصال واصل بهم يومًا، ثم يومًا، ثم رأوا الهلال فقال: لو تأخر لزدتكم كالمُنَكِّل لهم حين أبَوا أن ينتهوا.","link":"https://binbaz.org.sa/fatwas/24647/علام-يحمل-سرد-بعض-الصحابة-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا تُحمل الروايات التي عن الصحابة أنهم كانوا يسردون الصوم.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4387,"question":"هل تتابع صيام ست من شوال أفضل من تفرقتها؟","title":"هل التتابع أفضل في صيام ست شوال؟","answer":"الجواب: المتابعة نعم، الست إذا تابعها أفضل لأنه مسارعة في الخير.\nس: إذا صام الست مع أيام البيض ووافق الاثنين والخميس هل يأخذ الأجر؟\nالشيخ: إذا نوى الست له أجرها.\nس: مع الأيام البيض؟\nالشيخ: لا، له أجر الست التي نواها.","link":"https://binbaz.org.sa/fatwas/24664/هل-التتابع-افضل-في-صيام-ست-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما أفضل في صيام ست شوال التتابع أم التفريق.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4388,"question":"البيض هل جاء في فضل صيامها حديث؟","title":"هل صيام الأيام البيض ثابت بالسنة؟","answer":"الجواب: أحاديث نعم، الثالث عشر، والرابع عشر، والخامس عشر.\nس: تحديدها بهذا من الرسول ﷺ؟\nالشيخ: نعم نعم.","link":"https://binbaz.org.sa/fatwas/24665/هل-صيام-الايام-البيض-ثابت-بالسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ورد حديث في فضل صيام الأيام البيض.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4919,"question":"يقول السائل: ما هو صيام الدهر؟ وهل يجوز صيام أيام متتالية استنادًا للحديث الذي فيما معناه أن النبي ﷺ كان يسأل أهله عن الإفطار فإذا لم يجد ينوي الصيام، ثم يقول: وهل يجوز لي الصيام لظروف مادية صعبة؟","title":"ما معنى صوم الدهر وحكم الصوم لظروف المعيشة؟","answer":"لا بأس في النافلة؛ إن شاء صام من أثناء النهار إذا لم يأكل سابقًا، يصوم من أثناء النهار، لا بأس، وله أن يفطر، المتنفل. ولكن سَرْدُ الصيام ينبغي له أن يكون يوم بعد يوم، إذا أراد السَّرْد يفطر يومًا ويصوم يومًا، وإنْ سَرَدَ أيامًا ثم أفطر بعددها؛ فلا بأس، كما كان عبدالله بن عمرو يفعل في آخر حياته، لما تعب كان يصوم أيامًا كثيرة يسردها، ثم يفطر بعددها؛ لأنها أقوى له.","link":"https://binbaz.org.sa/fatwas/25436/ما-معنى-صوم-الدهر-وحكم-الصوم-لظروف-المعيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو صيام الدهر وهل يجوز الصيام لظروف مادية صعبة.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4920,"question":"يقول السائل: هل يشترط تبييت النية لصيام الست من شوال؟ وإذا استيقظ إنسان في الضحى في يوم من أيام شوال ولم يأكل شيئًا فهل يُحسب صيام  هذا اليوم؟","title":"هل يشترط تبييت النية لصيام الست من شوال؟","answer":"التطوع ما يشترط له التبييت بالنية، لو صام من أثناء النهار لا بأس، يكون ناقصًا، وإذا صام من أول النهار أفضل أكمل. وإذا ما صام إلا من أثناء النهار صار صيامه ناقصًا.","link":"https://binbaz.org.sa/fatwas/25438/هل-يشترط-تبييت-النية-لصيام-الست-من-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تبييت النية لصيام الست من شوال.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":4983,"question":"الصيام غدًا على أنه يوم الإثنين وهو يوم خمسة عشر؟","title":"حكم الجمع بين صيام الإثنين وخمسة عشر","answer":"الجواب: ما في حرج، لا بأس؛ يصوم يوم الإثنين سواء كان خمسة عشر ولا غيره، ما في بأس.","link":"https://binbaz.org.sa/fatwas/28482/حكم-الجمع-بين-صيام-الاثنين-وخمسة-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الجمع بين صيام الاثنين وخمسة عشر.mp3","categories":["شروح الحديث","صيام التطوع"]},{"id":5846,"question":"يقول: لا حياء في الدين، أنا شاب أريد أن أتزوج، ولكن أريد أن أعرف كيف أباشر زوجتي طبق ما فعله الرسول ﷺ؟ وما الذي أرتديه من الملابس؟ وهل أبتعد عنها إذا كانت حاملًا وشكرًا؟","title":"كيفية النكاح الشرعي","answer":"الجواب: الزواج معروف، يتزوج، يعني يخطب المرأة، يسأل عن دينها، وعن حالها، وإذا عرف أنها صالحة له مسلمة، أو رآها يتزوج الزواج الشرعي، يقوم وليها يعقد له عند بعض طلبة العلم الذين يعرفون؛ حتى يبينون له ما ينبغي، ويقول: زوجتك، والزوج يقول: قبلت بحضرة شاهدين عدلين، أربعة: الولي، والزوج، وشاهدان، ويقول الولي: زوجتك، ويقول: قبلت على مال بينهما معروف على حسب ما تيسر.  وإذا دخل عليها ذكر بعض أهل العلم أنه يصلي ركعتين أفضل، فإذا صلى ركعتين؛ حسن، يدعو الله -جل وعلا- أن يوفق بينهما، وإذا لمسها يسأل الله خيرها، وخير ما جبلت عليه، ويتعوذ بالله من شرها، وشر ما جبلت عليه، ثم إذا شاء الاتصال بها اتصل بها.  وإذا كانت حبلى، فالنكاح باطل، إذا كان دخل عليها، وهي حبلى؛ فهذا نكاح باطل، أما إذا حملت منه هو؛ فلا بأس أن يطأها وهي حامل، ولكن لا يطأها وهي حائض، ولا نفساء، الحائض، والنفساء لا توطأ، أما الحامل؛ فلا بأس أن يطأها وهي حامل إذا كان حملها منه، أما إذا كان دخل عليها، ووجدها حاملًا، فهذه لها عدة من غيره، وهو نكاح باطل، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1193/كيفية-النكاح-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_189.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":5935,"question":"ما حكم مؤخر الصداق؟ وهل نصف دينه بالزواج، ويتقي الله بالنصف الآخر، من أين هذا القول؟","title":"ما صحة القول بأن الزواج شطر الدين","answer":"الجواب: يروى عن النبي ﷺ في حديث في سنده نظر إذا تزوج الإنسان؛ فقد أحرز شطر دينه؛ فليتق الله في الشطر الآخر جاء هذا من طرق لا تخلو من ضعف عند أهل العلم، ولا شك أن الزواج مهم، ولكن كونه الشطر محل نظر! إنما هو مهم، الله يقول -جل وعلا-: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32].  ويقول : وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ الآية [النساء:3] والرسول ﷺ أمر بالنكاح -كما سمعتم- وحث الشباب على ذلك، وقال: تزوجوا الودود الولود؛ فإني مكاثر بكم الأمم يوم القيامة فالرسول ﷺ حث على هذا، ورغب فيه كما أمر به الله  لكن كونه شطر الدين هذا محل نظر؛ لضعف الحديث. ولكن ينبغي للمؤمن أن يحرص عليه، وهو شعبة من الدين، وفرض من الفرائض، ومن أسباب العفة، وغض البصر، ومن أسباب الاستقامة، ومن أسباب صلاح المجتمع، ومن أسباب كثرة النسل، وكثرة الأمة، وكثرة من يعبد الله  فينبغي الجد في ذلك، ولكن ينبغي له أن يختار المرأة الصالحة. وإن تيسر أنه ينظر للمرأة قبل الزواج؛ فهو أحسن، النبي ﷺ أمر الخاطب أن ينظر أخبر ﷺ إذا خطب أحدكم امرأة، فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها؛ فليفعل. وسأله رجل قال: يا رسول الله، إني خطبت فلانة، فقال: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها فإذا تيسر النظر إليها؛ فهو أولى، وينبغي لأهلها أن يسمحوا بذلك، تنظره، وينظرها، لا بأس. لكن في محل ما فيه خلوة، ينظر إليها، وتنظر إليه مع حضور والدها، أو أمها، أو أخيها، يعني ليس في خلوة في مكان ما فيه خلوة، لا يخلو بها؛ لأن الخلوة من أسباب وقوع الفاحشة. وكذلك ما نبه عليه الشيخ صالح ما قد يقع من بعض الناس، أنا ما سمعته من المسلمين، لكن موجود في الخارج، وهو أن يسافر معها، ولم يعقد عليها؛ حتى ينظر إليها، وتنظر إليه، فهذا من البلاء العظيم، والمنكر الفظيع، نعوذ بالله، إنما مجرد نظر ينظر إليها، وتنظر إليه فقط، أما أن يخلو بها، ويسافر معها، وتسافر معه؛ فهذا منكر كبير، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1286/ما-صحة-القول-بان-الزواج-شطر-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_273.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":6149,"question":"عن ابن عباس -رضي الله عنهما-: كان رسول الله ﷺ لا يفطر الأيام البيض، لا في سفر، ولا حضر، فهل هذا ثبت عن رسول الله؟","title":"ما صحة حديث: «كان رسول الله لا يفطر الأيام البيض»؟","answer":"الجواب:  ما نعلم صحته، بل ثبت عنه أنه كان يسرد الصوم بعض الأحيان حتى يقال: لا يفطر، ويسرد الإفطار حتى يقال: لا يصوم، ثبت هذا من حديث ابن عباس، وعائشة، وغيرهما عنه -عليه الصلاة والسلام- فقد يصومها، وقد لا يصومها، عليه الصلاة والسلام. ولكنها سنة صيامها سنة، قد يصومها -عليه الصلاة والسلام- في بعض الأحيان، وقد يشغل عنها، فلا يصومها، ويسرد الصوم في أوقات أخرى، كما أنه يصوم الإثنين، والخميس، فقد يشغل عنهما، فلا يصومها، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1606/ما-صحة-حديث-كان-رسول-الله-لا-يفطر-الايام-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_500.mp3","categories":["صيام التطوع"]},{"id":6278,"question":"من كان عليه صيام فرض من شهر رمضان هل يجوز له أن يصوم نفلاً قبل أن يقضي الفرض الذي كان عليه؟","title":"حكم صيام النفل قبل صيام قضاء الفرض","answer":"الجواب:  فيه خلاف بين أهل العلم، ولكن الأرجح أنه لا يبدأ إلا بالفرض، إذا كان عليه فرض قضاء رمضان يبدأ بهذا الفرض قبل التطوع لأن هذا أهم.","link":"https://binbaz.org.sa/fatwas/1792/حكم-صيام-النفل-قبل-صيام-قضاء-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_631.mp3","categories":["صيام التطوع"]},{"id":6723,"question":"من كان عليه قضاء يومين من رمضان، ويريد أن يصومهما يوم التاسع، والعاشر، فهل تجزئه عن القضاء، وعن يوم عاشوراء؟","title":"حكم صيام عاشوراء قضاءً","answer":"الجواب:  لا شك أن قضاء الصوم الواجب أهم من النوافل، فإذا كان على الإنسان أيام من رمضان، أو أيام منذورة، أو كفارات؛ فهي أهم من النافلة، وإذا صام يوم عرفة، أو يوم عاشوراء من القضاء؛ فلا بأس، ونرجو أن يجمع الله له الخيرين، والأجرين إذا كان لم يمنعه من صوم عاشوراء إلا قضاء اليوم الذي عليه، والأيام التي عليه، فيرجى له فضل هذا، وهذا.","link":"https://binbaz.org.sa/fatwas/2590/حكم-صيام-عاشوراء-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1086.mp3","categories":["صيام التطوع"]},{"id":6771,"question":"إذا جلس إلى أول شهر رجب، وصام الشهر كاملًا، ودائمًا، ما حكمه؟الشيخ: شعبان؟ الطالب: رجب.","title":"حكم صوم شهر رجب كاملاً","answer":"الجواب: مكروه، ما يصام رجب، هذا من عمل الجاهلية. السؤال: يعني دائمًا؟ الجواب: لا ما ينبغي، مكروه، ما ينبغي؛ لأن الجاهلية كانت تفعله، أما المسلمون ما يفعلونه، ينهى عن التطوع في رجب، أما إذا صام الاثنين، والخميس من كل أسبوع، أو صام ثلاثة أيام من كل شهر، من رجب، وغيره؛ هذا طيب، لو صام شعبان، النبي كان يصوم شعبان -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2641/حكم-صوم-شهر-رجب-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1137.mp3","categories":["صيام التطوع"]},{"id":7119,"question":"شابة تريد الصيام الاثنين والخميس، لكن والدتها تمنعها عن الصيام بحجة أنها في السن صغيرة، فماذا تفعل؟ هل تطيع والدتها مع قدرتها على الصوم؟","title":"حكم تقديم صيام التطوع على طاعة الوالدة","answer":"الجواب:\n\nنعم نعم، صوم النافلة مستحب، وطاعة الوالدة واجبة، والوالدة قصدها الخير، وقصدها أن ترحم حالها، ولا تشق على نفسها، لكن ينبغي لها أن تعالج الموضوع بالحكمة، والكلام الطيب، والأسلوب الحسن؛ حتى تسمح أمها بالصيام إذا كان الصوم لا يشق عليها ولا يؤثر عليها.\n\nفالمقصود: أن هذا من الوالدة من باب العطف والرحمة، فلا ينبغي للبنت أن تعصيها، ويكون بينها وبينها الشر، ولكن تعالج الموضوع بالكلام الطيب، والأسلوب الحسن مع الوالدة؛ حتى ترضى -إن شاء الله- وحتى تمكن من صوم بلا مشقة.","link":"https://binbaz.org.sa/fatwas/3152/حكم-تقديم-صيام-التطوع-على-طاعة-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1510.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":7517,"question":"سماحة الشيخ! هذا سؤال يقول مرسله (ج. س. ك). هل يشرع صيام الست من شوال لمن عليه أيام من رمضان قبل قضاء ما عليه؛ لأني سمعت بعض الناس يفتي بذلك، ويقول: إن عائشة رضي الله عنها كانت لا تقضي الأيام التي عليها من رمضان إلا في شعبان، والظاهر أنها كانت تصوم الست من شوال لما هو معلوم من حرصها على الخير؟","title":"هل يشرع صيام الست من شوال لمن عليه قضاء؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه المسألة لا يجوز فيما يظهر لنا أن تصام النافلة قبل الفريضة لأمرين:\nأحدهما: أن الرسول عليه الصلاة والسلام قال: من صام رمضان ثم أتبعه ستاً من شوال كان كصيام الدهر والذي عليه قضاء من رمضان لا يكون متبعاً الست من شوال لرمضان؛ لأنه قد بقي عليه بعض رمضان، فلا يكون متبعاً لها لرمضان حتى يكمل ما عليه من رمضان، فإذا كان الرجل عليه صيام من رمضان لكونه مسافراً أو مريضاً ثم عافاه الله، فإنه يبدأ بقضاء رمضان ثم يصوم الست إن أمكنه ذلك، وهكذا المرأة التي أفطرت من أجل حيضها أو نفاسها، فإنها تبدأ بقضاء الأيام التي عليها ثم تصوم الست من شوال إن أمكنها ذلك إذا قضت في شوال، أما أن تبدأ بصيام الست من شوال، أو يبدأ الرجل الذي عليه صوم الست من شوال، فهذا لا يصلح ولا ينبغي.\nوالوجه الثاني: أن دين الله أحق بالقضاء، وأن الفريضة أولى بالبدء والمسارعة من النافلة، الله عز وجل أوجب عليه صوم رمضان، وأوجب على المرأة صوم رمضان، فلا يليق أن تبدأ بالنافلة قبل أن تؤدي الفريضة، وبهذا يعلم أنه لا وجه للفتوى بصيام الست لمن عليه قضاء قبل القضاء بل يبدأ بالقضاء فيصوم الفرض، ثم إذا بقي في الشهر شيء وأمكنه أن يصوم الست فعل ذلك وإلا ترك؛ لأنها نافلة بحمد الله، وأما قضاء الصيام الذي عليه من رمضان فهو واجب وفرض، فوجب أن يبدأ بالفرض قبل النافلة ويحتاط لدينه للأمرين السابقين:\nأحدهما: أن الرسول ﷺ قال: ثم أتبعه ستاً من شوال والذي عليه أيام من رمضان ما يصلح أن يكون متبعاً للست لرمضان، بل قد بقي عليه شيء، فكأنه صامها في أثناء الشهر، كأنه صامها بين أيام رمضان، ما جعلها متبعة لرمضان.\nوالأمر الثاني: أن الفرض أولى بالبداءة وأحق بالقضاء من النفل، ولهذا جاء في الحديث الصحيح: دين الله أحق بالقضاء، اقضوا الله، فالله أحق بالوفاء سبحانه وتعالى. نعم.\nأما قوله عن عائشة ، فـعائشة رضي الله عنها كانت تؤخر الصوم إلى شعبان قالت: للشغل برسول الله عليه الصلاة والسلام فإذا أخرت الفريضة من أجل الرسول ﷺ، فأولى وأولى أن تؤخر النافلة من أجل شغله عليه الصلاة والسلام.\nفالحاصل: أن عائشة ليس في عملها حجة لتقديم الست من شوال على قضاء رمضان؛ لأنها تؤخر صيام رمضان من أجل شغلها برسول الله عليه الصلاة والسلام، فأولى وأولى أن تؤخر الست من شوال.\nثم لو فعلت وقدمت الست من شوال، فليس فعلها حجة فيما يخالف ظاهر النصوص. نعم.","link":"https://binbaz.org.sa/fatwas/4490/هل-يشرع-صيام-الست-من-شوال-لمن-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_009/00901.mp3","categories":["صيام التطوع"]},{"id":7577,"question":"سماحة الشيخ! هذه الرسالة وردتنا من الكويت من المستمع عيسى بن علي بن المعتوق يقول في رسالته: السلام عليكم ورحمة الله وبركاته، وبعد: في يوم الإثنين الماضي كنت صائم صيام تطوع، فلما جئت من المدرسة نمت وكنت تعبان ومرهق قبل أن أصلي العصر لعدم دخول وقتها، ولكنني استيقظت بعد صلاة العشاء فأفطرت ثم صليت العصر والمغرب والعشاء قضاءً، فهل هذا العمل جائز أم أصلي ثم أفطر، وماذا في صيامي وصلاتي في هذه الحالة؟","title":"حكم صوم النافلة إذا أدى إلى التهاون بالفرائض","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله جل وعلا شرع لعباده صيام التطوع؛ لما في الصيام من الخير العظيم والفوائد الجمة، فإذا كان الصوم -أعني صوم التطوع- يدعو إلى ضعف وتعب شديد حتى يفوت الإنسان صلاته في الوقت وصلاته في الجماعة، فإنه في هذه الحال ينبغي له أن يدع الصيام الذي يضعفه عما أوجب الله، ويشتغل بما أوجب الله سبحانه وتعالى، ولا يصوم إلا إذا كان هناك نشاط وقوة على الصيام لا يقع معها تفريط فيما يجب. \nوهذا الذي فعلته أيها السائل من كونك نمت قبل العصر فلم تستيقظ إلا بعد العشاء ثم أفطرت ثم صليت العصر ثم المغرب والعشاء، كل ذلك لا بأس به، وكونك تبادر بالفطر أولى حتى تنشط على العبادة، وأيضاً هذا هو الموافق للسنة، فإن السنة البدار بالفطر بعد غروب الشمس، ولكن ينبغي لك في مثل هذا أن لا تنام إلا وقد جعلت عندك منبهاً ينبهك عند وقت الصلاة، أعني الساعة المنبهة، أو توصي من حولك من أهل البيت أن يوقظوك عند دخول الوقت، ولا تتساهل في هذا الأمر، فإن التساهل يعتبر تفريطاً فيما أوجب الله سبحانه وتعالى، فلا يجوز للمؤمن أن يفرط في أداء الواجبات بل يجب عليه أن يحتاط وأن يعتني بما يعينه على أداء الواجب من الصلوات وغيرها، وإذا كان الإنسان قد يغلبه النوم إذا نام بعد الظهر فينبغي له أن يدع عنده ساعة منبهة على الوقت تنبهه للصلاة، وهكذا في الليل، إذا كان يخشى أن لا يقوم من آخر الليل لصلاة الفجر فإنه يضع ساعة منبهة تعينه على القيام في الوقت، وكل شيء لا يتم الواجب إلا به فهو واجب. \nفأداء الصلاة في الوقت أمر لازم وأمر واجب، فإذا كان الإنسان نومه ثقيل ويخشى من فوات الوقت أو فوات الصلاة في الجماعة، فإنه يعمل ما يستطيع مما يعنيه على أداء الصلاة في الوقت وعلى أدائها في الجماعة من وجود منبه يوقت الساعة على الوقت المناسب، أو وجود منبه من أهله ينبهه وقت الصلاة حتى لا يفرط فيما أوجب الله، وحتى لا يقع في محارم الله سبحانه وتعالى. \nوعليك عن تفريطك التوبة والاستغفار، هذا نوع من التفريط فعليك أن تستغفر الله وأن تتوب إليه بالندم على ما مضى، والعزم الصادق أن لا تعود في مثل هذا التفريط، ونسأل الله لنا ولك التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/4583/حكم-صوم-النافلة-اذا-ادى-الى-التهاون-بالفراىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01801.mp3","categories":["صيام التطوع"]},{"id":8436,"question":"أولى رسائل هذه الحلقة: شيخ عبد العزيز رسالة وصلت إلينا من الأردن، محافظة الكرك، باعثها أخونا سعيد عيد أبو عبدون ، أخونا يقول: هل يجوز للإنسان أن يختار صيام ستة أيام من شهر شوال أم أن صيام هذه الأيام لها وقت معلوم؟ وهل إذا صام المسلم هذه الأيام تصبح فرضاً عليه، ويجب عليه صيامها كل عام؟","title":"حكم صيام الست من شوال متتابعة ومفرقة وصومها وتركها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من صام رمضان ثم أتبعه ستاً من شوال كان كصيام الدهر، خرجه الإمام مسلم في صحيحه، وهذه الست ليس لها أيام معدودة معينة، بل يختارها المؤمن من جميع الشهر، فإن شاء صامها في أوله، وإن شاء صامها في أثنائه، وإن شاء صامها في آخره، وإن شاء فرقها، صام بعضها في أوله، وبعضها في وسطه، وبعضها في آخره، الأمر واسع بحمد الله، وإن بادر إليها وتابعها في أول الشهر كان ذلك أفضل من باب المسارعة إلى الخير، ولكن ليس في هذا ضيق بحمد الله، بل الأمر فيها واسع إن شاء تابع وإن شاء فرق، ثم إذا صامها بعض السنين وتركها بعض السنين فلا بأس؛ لأنها نافلة، تطوع ليست فريضة، فإذا صامها في بعض السنين وتركها في بعض السنين، أو صام بعضها وترك بعضها فلا حرج عليه والحمد لله.","link":"https://binbaz.org.sa/fatwas/6320/حكم-صيام-الست-من-شوال-متتابعة-ومفرقة-وصومها-وتركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12001.mp3","categories":["صيام التطوع"]},{"id":8483,"question":"إذا صامت يوم عاشوراء ويوم عرفات والثلاثة الأيام البيض، هل يجزئ ذلك عن تلك الأيام التي أفطرتها؟","title":"حكم صيام يوم عرفة والأيام البيض وعاشوراء قضاءً","answer":"الجواب: إذا صامتها بالنية إذا صامت يوم عاشوراء أو عرفة أو أيام البيض بالنية عما عليها من القضاء أجزأ ذلك، (الأعمال بالنيات).","link":"https://binbaz.org.sa/fatwas/6542/حكم-صيام-يوم-عرفة-والايام-البيض-وعاشوراء-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12510.mp3","categories":["صيام التطوع"]},{"id":8778,"question":"يقول: ما كيفية زيارة مسجد الرسول ﷺ؟ وهل الأدعية الواردة في كتيبات الزيارة التي يزور بها المزورون في الأماكن المقدسة صحيحة أم لا؟ وأرشدونا عن كيفية الزيارة الصحيحة؟","title":"ما هي الأعمال المستحبة عند زيارة مسجد النبي؟","answer":"الجواب: زيارة مسجد الرسول ﷺ سنة؛ لأنها أحد المساجد الثلاثة، وقد قال فيه النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى فشد الرحال إلى هذه الثلاثة سنة وقربة وطاعة، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام فقصد هذا المسجد العظيم للصلاة فيه والقراءة فيه والتعبد أمر مطلوب وشرعي، وهكذا المسجد الحرام مسجد مكة، وهكذا المسجد الأقصى القدس، كل هذه الثلاثة المساجد قصدها وشد الرحيل إليها قربة وطاعة، فإذا وصل إليها المؤمن صلى فيها ما يسر الله، وتعبد فيها بالاعتكاف أو بالقراءة أو بحضور حلقات العلم، كل هذا طيب. وأما مكة فيحصل فيها أيضاً زيادة على هذا: الطواف بالكعبة، ويمكن أداء العمرة كذلك والحج في وقته، هذا يختص بمكة، العمرة والحج هذا من خصائص مكة. أما مسجد النبي ﷺ فالزائر له مثل بقية المساجد يصلي فيه، يتعبد بالقراءة، بحضور حلقات العلم بالإكثار من ذكر الله ، كل هذا مطلوب، وهكذا الاعتكاف، وهكذا المسجد الأقصى إذا زاره المؤمن صلى فيه وقرأ فيه وذكر الله فيه وتعبد فيه بأنواع العبادة من الصلاة والذكر والقراءة والاعتكاف ونحو ذلك كل هذا مشروع.\nويستحب لمن زار المدينة: أن يسلم على النبي ﷺ وعلى صاحبيه، فيتوجه بعدما يصلي ركعتين في المسجد إذا صلاها في الروضة كان أفضل، إذا صلى الركعتين في الروضة كان أفضل وإن صلاها في بقية المسجد كفى ذلك، ثم بعد هذا يتوجه إلى قبره عليه الصلاة والسلام فيقف أمامه عليه الصلاة والسلام ويسلم عليه عليه الصلاة والسلام ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، صلى الله وسلم عليك وعلى آلك وأصحابك، ويدعو له، يقول: جزاك الله عن أمتك خيراً، أشهد أنك قد بلغت الرسالة، وأديت الأمانة، ونصحت الأمة، وجاهدت في الله حق جهاده.. إذا قال هذا الكلام هذا كلام طيب وصحيح وصدق، ثم يتقدم قليلاً فيسلم على الصديق  أبو بكر فيقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً.. رضي الله عنك، ثم يتقدم قليلاً ويسلم على عمر الفاروق  عمر بن الخطاب فيقول: السلام عليك يا عمر بن الخطاب ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً ورضي الله عنك، ويدعو لهما ثم ينصرف، هذا هو المشروع في السلام على الرسول ﷺ وعلى صاحبيه الصديق وعمر رضي الله تعالى عنهما.\nويشرع له أيضاً أن يزور البقيع فيسلم على أصحاب البقيع ويدعو لهم بالمغفرة والرحمة؛ لأن الرسول كان يزورهم عليه الصلاة والسلام، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية. هكذا يسلم على أهل القبور ويدعو لهم: اللهم اغفر لهم وارحمهم، مثلما دعا النبي ﷺ لأهل البقيع، وهكذا يستحب له أن يزور الشهداء شهداء أحد فيدعو لهم ويستغفر لهم ويترحم عليهم  وأرضاهم، هذا هو المشروع.\nأما ما يفعله بعض الجهلة كونه يدعو النبي ﷺ، أو يستغيث به، أو يتمسح بجدران الحجرة هذا منكر لا يجوز، ولكن يسلم وهو واقف من غير أن يمسح الحجرة أو القضبان أو الجدران أو الأسطوانات، كل هذا غير مشروع بل بدعة، لا يتمسح بالجدران ولا بالأسطوانات ولا بقضبان الشبك ولا بغير هذا، ولكن يقف أمام النبي ﷺ ويسلم وهكذ أمام الصديق ، وأمام عمر رضي الله عنهما ويسلم ثم ينصرف، هذا هو المشروع، ولا يدعو النبي ﷺ ولا يدعو غيره، لا يقل: يا رسول الله! انصرني أو اشفع لي، أو أغثني، أو المدد المدد، هذا منكر لا يجوز بل هو من الشرك الأكبر، وهكذا عند الصحابيين الصديق وعمر رضي الله عنهما لا يقل لهما: أغيثاني أو انصراني أو المدد المدد كما يفعل بعض الجهلة عند بعض القبور، هذا منكر، بل هذا من الشرك، طلب الغوث من الميت والمدد من الميت هذا من الشرك الأكبر عند أهل العلم، وهكذا عند زيارة قبور البقيع لا يقل لهم: المدد المدد، ولا انصروني، أو اشفوا مريضي، أو اشفعوا لي لا، ولكن يسلم عليهم ويدعو لهم بالمغفرة والرحمة ثم ينصرف، وهكذا شهداء أحد إذا سلم عليهم يدعو لهم كما دعا لهم النبي ﷺ ويستغفر لهم ويترحم عليهم وينصرف.\nويستحب لمن زار المدينة أيضاً أن يزور مسجد قباء ويصلي فيه ركعتين كما كان النبي يزوره عليه الصلاة والسلام، وأخبر ﷺ أن من زاره.. أن من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة. فزيارة مسجد قباء سنة وقربة تأسياً بالنبي عليه الصلاة والسلام في ذلك، هذا هو المشروع لمن زار المدينة، أما كونه يقصد محلات أخرى آبار أو مساجد أخرى أو بقاع هذا غير مشروع، المشروع لمن زار المدينة هو ما ذكرنا: أولاً: الصلاة في مسجد النبي ﷺ، ثم السلام على النبي ﷺ وعلى صاحبيه، ثم زيارة البقيع، ثم زيارة الشهداء، ثم زيارة مسجد قباء، كل هذه سنة وليست واجبة، لو أنه ما زارها ما فيه شيء، ولكن هذا سنة ومستحب وليس بواجب. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6933/ما-هي-الاعمال-المستحبة-عند-زيارة-مسجد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21906.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":8779,"question":"يقول: ما كيفية زيارة مسجد الرسول ﷺ؟ وهل الأدعية الواردة في كتيبات الزيارة التي يزور بها المزورون في الأماكن المقدسة صحيحة أم لا؟ وأرشدونا عن كيفية الزيارة الصحيحة؟","title":"ما هي الأعمال المستحبة عند زيارة مسجد النبي؟","answer":"الجواب: زيارة مسجد الرسول ﷺ سنة؛ لأنها أحد المساجد الثلاثة، وقد قال فيه النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى فشد الرحال إلى هذه الثلاثة سنة وقربة وطاعة، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام فقصد هذا المسجد العظيم للصلاة فيه والقراءة فيه والتعبد أمر مطلوب وشرعي، وهكذا المسجد الحرام مسجد مكة، وهكذا المسجد الأقصى القدس، كل هذه الثلاثة المساجد قصدها وشد الرحيل إليها قربة وطاعة، فإذا وصل إليها المؤمن صلى فيها ما يسر الله، وتعبد فيها بالاعتكاف أو بالقراءة أو بحضور حلقات العلم، كل هذا طيب. وأما مكة فيحصل فيها أيضاً زيادة على هذا: الطواف بالكعبة، ويمكن أداء العمرة كذلك والحج في وقته، هذا يختص بمكة، العمرة والحج هذا من خصائص مكة. أما مسجد النبي ﷺ فالزائر له مثل بقية المساجد يصلي فيه، يتعبد بالقراءة، بحضور حلقات العلم بالإكثار من ذكر الله ، كل هذا مطلوب، وهكذا الاعتكاف، وهكذا المسجد الأقصى إذا زاره المؤمن صلى فيه وقرأ فيه وذكر الله فيه وتعبد فيه بأنواع العبادة من الصلاة والذكر والقراءة والاعتكاف ونحو ذلك كل هذا مشروع.\nويستحب لمن زار المدينة: أن يسلم على النبي ﷺ وعلى صاحبيه، فيتوجه بعدما يصلي ركعتين في المسجد إذا صلاها في الروضة كان أفضل، إذا صلى الركعتين في الروضة كان أفضل وإن صلاها في بقية المسجد كفى ذلك، ثم بعد هذا يتوجه إلى قبره عليه الصلاة والسلام فيقف أمامه عليه الصلاة والسلام ويسلم عليه عليه الصلاة والسلام ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، صلى الله وسلم عليك وعلى آلك وأصحابك، ويدعو له، يقول: جزاك الله عن أمتك خيراً، أشهد أنك قد بلغت الرسالة، وأديت الأمانة، ونصحت الأمة، وجاهدت في الله حق جهاده.. إذا قال هذا الكلام هذا كلام طيب وصحيح وصدق، ثم يتقدم قليلاً فيسلم على الصديق  أبو بكر فيقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً.. رضي الله عنك، ثم يتقدم قليلاً ويسلم على عمر الفاروق  عمر بن الخطاب فيقول: السلام عليك يا عمر بن الخطاب ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً ورضي الله عنك، ويدعو لهما ثم ينصرف، هذا هو المشروع في السلام على الرسول ﷺ وعلى صاحبيه الصديق وعمر رضي الله تعالى عنهما.\nويشرع له أيضاً أن يزور البقيع فيسلم على أصحاب البقيع ويدعو لهم بالمغفرة والرحمة؛ لأن الرسول كان يزورهم عليه الصلاة والسلام، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية. هكذا يسلم على أهل القبور ويدعو لهم: اللهم اغفر لهم وارحمهم، مثلما دعا النبي ﷺ لأهل البقيع، وهكذا يستحب له أن يزور الشهداء شهداء أحد فيدعو لهم ويستغفر لهم ويترحم عليهم  وأرضاهم، هذا هو المشروع.\nأما ما يفعله بعض الجهلة كونه يدعو النبي ﷺ، أو يستغيث به، أو يتمسح بجدران الحجرة هذا منكر لا يجوز، ولكن يسلم وهو واقف من غير أن يمسح الحجرة أو القضبان أو الجدران أو الأسطوانات، كل هذا غير مشروع بل بدعة، لا يتمسح بالجدران ولا بالأسطوانات ولا بقضبان الشبك ولا بغير هذا، ولكن يقف أمام النبي ﷺ ويسلم وهكذ أمام الصديق ، وأمام عمر رضي الله عنهما ويسلم ثم ينصرف، هذا هو المشروع، ولا يدعو النبي ﷺ ولا يدعو غيره، لا يقل: يا رسول الله! انصرني أو اشفع لي، أو أغثني، أو المدد المدد، هذا منكر لا يجوز بل هو من الشرك الأكبر، وهكذا عند الصحابيين الصديق وعمر رضي الله عنهما لا يقل لهما: أغيثاني أو انصراني أو المدد المدد كما يفعل بعض الجهلة عند بعض القبور، هذا منكر، بل هذا من الشرك، طلب الغوث من الميت والمدد من الميت هذا من الشرك الأكبر عند أهل العلم، وهكذا عند زيارة قبور البقيع لا يقل لهم: المدد المدد، ولا انصروني، أو اشفوا مريضي، أو اشفعوا لي لا، ولكن يسلم عليهم ويدعو لهم بالمغفرة والرحمة ثم ينصرف، وهكذا شهداء أحد إذا سلم عليهم يدعو لهم كما دعا لهم النبي ﷺ ويستغفر لهم ويترحم عليهم وينصرف.\nويستحب لمن زار المدينة أيضاً أن يزور مسجد قباء ويصلي فيه ركعتين كما كان النبي يزوره عليه الصلاة والسلام، وأخبر ﷺ أن من زاره.. أن من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة. فزيارة مسجد قباء سنة وقربة تأسياً بالنبي عليه الصلاة والسلام في ذلك، هذا هو المشروع لمن زار المدينة، أما كونه يقصد محلات أخرى آبار أو مساجد أخرى أو بقاع هذا غير مشروع، المشروع لمن زار المدينة هو ما ذكرنا: أولاً: الصلاة في مسجد النبي ﷺ، ثم السلام على النبي ﷺ وعلى صاحبيه، ثم زيارة البقيع، ثم زيارة الشهداء، ثم زيارة مسجد قباء، كل هذه سنة وليست واجبة، لو أنه ما زارها ما فيه شيء، ولكن هذا سنة ومستحب وليس بواجب. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6933/ما-هي-الاعمال-المستحبة-عند-زيارة-مسجد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21906.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":8855,"question":"هنا رسالة أرجو أن يتسع لها ما بقي من وقت البرنامج من العراق يقول: هل ورد شيء عن رسول الله ﷺ يؤكد صيامه ليومي الإثنين والخميس من كل أسبوع وعلى مدار السنة؟","title":"مشروعية صيام الإثنين والخميس","answer":"الجواب: نعم، ثبت عن رسول الله ﷺ أنه كان يصوم الإثنين والخميس ويقول: إنهما يومان تعرض فيهما الأعمال على الله، فأحب أن يعرض عملي وأنا صائم رواه مسلم في الصحيح، وربما شغل عن ذلك في بعض الأوقات ...... الإفطار لمشاغل من ضيوف أو غير ذلك ثم يسرد الصوم بعد ذلك، كما قالت عائشة رضي الله عنها: كان النبي ﷺ يصوم حتى نقول: لا يفطر، ويفطر حتى نقول: لا يصوم وهكذا جاء عن ابن عباس وغيره مما يدل على هذا المعنى، وهو أنه ﷺ ربما سرد الصوم لكونه قد فرغ لذلك، وربما سرد الإفطار لأسباب شغلته عن الصوم، وكان ﷺ يصوم الإثنين والخميس عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7010/مشروعية-صيام-الاثنين-والخميس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16612.mp3","categories":["صيام التطوع"]},{"id":8980,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من الأخ أسعد جاسم من العراق، أخونا له مجموعة من الأسئلة من بينها سؤال يقول: حدثونا عن المرأة وصيام النافلة، ماذا يجب عليها أن تفعل؟","title":"صيام النافلة للمرأة","answer":"الجواب: المرأة كالرجل، الواجب صوم رمضان فقط على المسلمين، أما ما سوى ذلك فمستحب مثل صيام ست من شوال، مثل صيام ثلاثة أيام من كل شهر، وإذا كانت في أيام البيض كان أفضل، ومثل صيام يوم الإثنين والخميس، هذه كلها عبادة، كلها عبادات وكلها نافلة، ولو صامت يومًا وأفطرت يومًا كذلك هذا أفضل الصيام فهو صيام داود عليه الصلاة والسلام للرجل والمرأة جميعًا، لكن ليس للمرأة أن تصوم وزوجها حاضر إلا بإذنه، ليس للمرأة أن تصوم وزوجها شاهد ليس بمسافر إلا بإذنه، هكذا قال النبي ﷺ قال: لا تصوم وزوجها شاهد إلا بإذنه، إلا رمضان هذا فريضة على الجميع.\nأما التطوع فليس لها أن تصوم إلا بإذنه، وينبغي له أن يأذن لها إذا كان ما في مشقة عليه وإن كان في مشقة عليه منعها من ذلك والحمد لله، وعليها أن تمتنع فرضا زوجها مقدم، وحاجة زوجها مقدمة. نعم.","link":"https://binbaz.org.sa/fatwas/7138/صيام-النافلة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17405.mp3","categories":["صيام التطوع"]},{"id":9396,"question":"ما هي فضيلة من صام يوم عرفة؟","title":"فضل صيام يوم عرفة","answer":"الجواب: من صام يوم عرفة له أجر عظيم، ثبت عن رسول الله عليه الصلاة والسلام: أن الله يكفر بصوم يوم عرفة السنة التي قبله والسنة التي بعده يعني: بشرط اجتناب الكبائر كما بينته الأحاديث الأخرى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7561/فضل-صيام-يوم-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18802.mp3","categories":["صيام التطوع"]},{"id":9724,"question":"يقول هذا السائل سماحة الشيخ! بأنه يصوم الإثنين والخميس من رجب وشعبان، هل هذه بدعة أم صحيح؟","title":"حكم صيام الإثنين والخميس من شهري رجب وشعبان","answer":"الجواب: لا حرج في ذلك إذا صام الإثنين والخميس من أي شهر لا بأس رجب شعبان غيرهما سنة. نعم.","link":"https://binbaz.org.sa/fatwas/7879/حكم-صيام-الاثنين-والخميس-من-شهري-رجب-وشعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27215.mp3","categories":["صيام التطوع"]},{"id":9729,"question":"من أفطر في صوم التطوع بدون عذر، هل عليه القضاء سماحة الشيخ؟","title":"حكم القضاء لمن أفطر في صيام التطوع","answer":"الجواب: ليس عليه قضاء، لكن يستحب له القضاء، إذا نوى يصوم الإثنين والخميس ثم أفطر بدون عذر فلا حرج عليه، لكن إذا قضى يكون أفضل، قد يكون جاءه ضيف يوم الإثنين أو اشتد عليه الحر وأفطر لا حرج الحمد لله: (المتطوع أمير نفسه) ليس بواجب، لكن الأفضل له إذا تيسر له القضاء يكون أفضل. نعم.","link":"https://binbaz.org.sa/fatwas/7884/حكم-القضاء-لمن-افطر-في-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27219.mp3","categories":["صيام التطوع"]},{"id":10217,"question":"سماحة الشيخ! تكثر أختنا من السؤال عن شهر رجب، وعن الصيام فيه، هل لرجب خصوصية معينة؟","title":"حكم إفراد شهر رجب بالصيام","answer":"الجواب: .... أنه يكره إفراده، يكره إفراده بالصوم تطوعاً؛ لأنه من شأن الجاهلية، كانوا يعظمونه بالصوم، فكره أهل العلم إفراده بالصوم تطوعاً، أما إذا صامه الإنسان عن صومٍ عليه من قضاء رمضان، أو من كفارة، فلا حرج في ذلك، أو صام منه ما شرع الله مثل أيام الإثنين والخميس، أو الثلاثة الأيام البيض، كل هذا لا حرج فيه، الحمد لله، مثل غيره من الشهور.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8383/حكم-افراد-شهر-رجب-بالصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31002.mp3","categories":["صيام التطوع"]},{"id":10221,"question":"سماحة الشيخ! تكثر أختنا من السؤال عن شهر رجب، وعن الصيام فيه، هل لرجب خصوصية معينة؟","title":"حكم إفراد شهر رجب بالصيام","answer":"الجواب: .... أنه يكره إفراده، يكره إفراده بالصوم تطوعاً؛ لأنه من شأن الجاهلية، كانوا يعظمونه بالصوم، فكره أهل العلم إفراده بالصوم تطوعاً، أما إذا صامه الإنسان عن صومٍ عليه من قضاء رمضان، أو من كفارة، فلا حرج في ذلك، أو صام منه ما شرع الله مثل أيام الإثنين والخميس، أو الثلاثة الأيام البيض، كل هذا لا حرج فيه، الحمد لله، مثل غيره من الشهور.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8383/حكم-افراد-شهر-رجب-بالصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31002.mp3","categories":["صيام التطوع"]},{"id":10227,"question":"أيضاً تسأل عن صيام الخميس والإثنين؟","title":"حكم صيام الإثنين والخميس","answer":"الجواب: سنة، صومهما سنة في حق الجميع، في حق الرجال والنساء، لكن إذا كانت ذات زوج؛ ليس لها الصوم إلا بإذنه؛ لأن المرأة التي عندها زوج ليس لها أن تصوم نافلة إلا بإذنه إذا كان حاضراً؛ لأن الرسول نهى عن هذا عليه السلام، قال: ليس للمرأة أن تصوم وزوجها شاهد إلا بإذن إلا رمضان فرمضان واجب على الجميع، لكن إذا أرادت أن تطوع بصوم الإثنين أو الخميس أو ستٍ من شوال، صوم ثلاثة أيام من الشهر، فلابد من استئذانه إذا كان حاضراً، إما إن كان غائباً فلا حرج أن تصوم بغير إذنه، إذا كان غائباً، يعني: مسافراً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8385/حكم-صيام-الاثنين-والخميس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31003.mp3","categories":["صيام التطوع"]},{"id":10320,"question":"في صيام التطوع إذا طرأت على الإنسان نية في النهار قبل أن يأكل شيئا فهل له ذلك؟","title":"حكم عدم تبييت النية من الليل في صيام التطوع","answer":"الجواب: نعم، له أن يصوم في النهار، إذا كان ما أكل شيء ولا تعاطى مفطراً فلا بأس، لو أصبح ما أكل شيئاً ولا تعاطى ما يفطره ثم أراد أن يصوم في الضحى فله ذلك، ثبت عن رسول الله ﷺ: أنه دخل على عائشة فسألها: هل عندها شيء؟ قالت: لا، قال: إني إذاً صائم، رواه مسلم في الصحيح.\nاحتج به العلماء على أن المتنفل له أن يصوم من أثناء النهار، إذا كان لم يتعاط مفطراً، وله أجره من حين نوى الصيام.\nأما المفترض لا، لابد أن يصوم من أول النهار، فلابد من طلوع الفجر، صاحب الفريضة عن رمضان أو عن كفارة أو عن نذر لابد أن تكون النية قبل طلوع الفجر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8495/حكم-عدم-تبييت-النية-من-الليل-في-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31408.mp3","categories":["صيام التطوع"]},{"id":10322,"question":"في صيام التطوع إذا دعي الإنسان لوليمة فأفطر فهل عليه إعادة لذلك اليوم الذي أفطره؟","title":"حكم قضاء من أفطر في صيام التطوع","answer":"الجواب: لا حرج، إذا أفطر لا قضاء عليه، المتنفل أمير نفسه، لكن الأفضل له أن يتمم ويعتذر يأتيهم ويجيب الدعوة، ويقول: إني صائم ويدعو لهم وينصرف، وإن رأى من المصلحة أن يفطر فلا حرج في ذلك.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8496/حكم-قضاء-من-افطر-في-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31409.mp3","categories":["صيام التطوع"]},{"id":10407,"question":"كيف صيام عاشوراء؟ وكيف صيام أيام هجرة الرسول ﷺ؟ وهل يجوز صيام اليوم العاشر منه؟ أرجو توضيح ذلك جزاكم الله خيرًا؟","title":"حكم صيام يوم عاشوراء وأيام الهجرة","answer":"الجواب: أما صيام عاشوراء فالسنة أن يصوم الإنسان اليوم العاشر من المحرم، وأن يصوم معه يومًا قبله أو يومًا بعده، والأفضل أن يصوم التاسع مع العاشر، لقول النبي ﷺ: لئن عشت إلى قابل لأصومن التاسع يعني: مع العاشر، والمروي عنه عليه الصلاة والسلام أنه قال: خالفوا اليهود وصوموا يومًا قبله أو يومًا بعده.\nفالسنة للمؤمن أن يصوم التاسع والعاشر جميعًا أو يصوم العاشر ومعه الحادي عشر، أو يصوم الثلاثة جميعًا التاسع والعاشر والحادي عشر، كل هذا فيه مخالفة لليهود، والمؤمن يخالفهم يعني: مأمور بمخالفة أعداء الله من أهل الكتاب ومن غيرهم من الكفرة.\nأما أيام الهجرة فلا يشرع صيامها، ولم يصم النبي ﷺ أيام الهجرة لا اليوم الأول ولا غيره، وهكذا يوم بدر، وأيام الأحزاب كلها لا تصام، وهكذا يوم الفتح كلها لم يشرع الله صيامها ، وإنما شرع لنا صيام يوم عاشوراء، صيام الإثنين والخميس، صيام ثلاثة أيام من كل شهر، وإذا صامها في أيام البيض كان أفضل، صيام ست من شوال بعد رمضان، كل هذه أمور مستحبة، أما أيام الهجرة فلا يشرع صيامها بل يكون بدعة إذا قصد ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8580/حكم-صيام-يوم-عاشوراء-وايام-الهجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34014.mp3","categories":["التاريخ والسيرة","صيام التطوع"]},{"id":10417,"question":"في سؤال لها آخر تقول فيه: هل يجوز للمرأة أن تصوم من غير إذن من زوجها لقضاء فرض أو تطوع؟ وهل يجوز له إذا علم أنها صائمة في وسط صيامها أي: في النهار أن يأمرها بأن تفطر أو يدعها تكمل؟ وهل يجوز صيامها وهو غير راضٍ وغاضب عليها إذا أصرت أن تصوم؟","title":"حكم صيام المرأة بدون إذن زوجها","answer":"الجواب: أما صوم الفرض كقضاء رمضان فهذا ليس له منعها ويجب عليه تمكينها، وليس لها طاعته في ذلك لو منعها، عليها القضاء؛ لأن الله جل وعلا أمرها بالقضاء وهكذا الرسول ﷺ، وقد أجمع المسلمون على: أنه يجب على المرأة إذا أفطرت في رمضان بسبب الحيض أو النفاس أن تقضي، وليس لزوجها أن يمنعها من ذلك.\nوأما التطوع: فإن كان غائبًا لا بأس، وإن كان شاهدًا فلا تصم إلا بإذنه، لقول النبي ﷺ: لا تصومن امرأة وزوجها حاضر إلا بإذنه، فإذا كان زوجك حاضرًا فليس لك الصوم إلا بإذنه، أعني: صوم التطوع كالخميس أو الإثنين أو ست من شوال أو صيام ثلاثة أيام من كل شهر ونحو ذلك، لابد من إذنه فإن أذن لك وإلا فلا تصومي.\nأما إن كان غائبًا مسافرا فلا بأس أن تصومي حال غيبته ولو بغير إذنه؛ لأنه حينئذ لا يتضرر بذلك وليس عليه حرج من ذلك، بخلاف حضوره فإنه قد يمنعه من بعض حاجاته.\nوالخلاصة: أنه لا يجوز لك الصوم بحضوره إذا كان الصوم تطوع إلا بإذنه، أما في حال الغيبة فلا بأس، وأما قضاء رمضان فالواجب عليك صومه وإن لم يأذن، لكن الكلام معه في ذلك واستسماحه حتى يأذن لك في تعجيل الصوم كلام حسن كلام طيب؛ لأن الإنسان لا يدري هل تطول حياته أم لا فإذا بادرت بالصوم وسارعت بالصوم فهو أحوط لك وليس له منعك من ذلك، يعني: قضاء ما عليك من رمضان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8590/حكم-صيام-المراة-بدون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34103.mp3","categories":["صيام التطوع","الحقوق الزوجية"]},{"id":10449,"question":"يسأل ويقول: ما هي الحكمة في منع الحاج من صوم يوم عرفة؟","title":"الحكمة في منع الحاج من صيام يوم عرفة","answer":"الجواب: المعروف عند العلماء أن الحكمة في ذلك أنه عيد للحجاج، أنه عيد لهم، فالأفضل لهم أن لا يصوموا؛ ولأن الفطر يقويهم على العمل والذكر والدعاء، والصوم قد يضعفهم ولاسيما في أيام الصيف وشدة الحر، فمن رحمة الله أن شرع لهم الفطر حتى يتقووا على الدعاء والعبادة، وهو عيد لهم كما قال ﷺ: يوم عرفة وأيام التشريق عيدنا أهل الإسلام، يوم عرفة ويوم النحر وأيام التشريق عيدنا أهل الإسلام هو عيد للمسلمين كما لا يصوم يوم النحر وأيام التشريق، ولا يجوز له صيامها فهكذا يوم عرفة، الأفضل أن لا يصوم، والنبي صامها مفطراً وشرب لبن والناس ينظرون عليه الصلاة والسلام حتى يتأسوا به، أما يوم العيد فلا يصام أبداً، حرام يصوم الناس كلهم لا في مكة ولا في غيرها، وهكذا أيام التشريق حرام صومه في مكة وفي غيرها، لا تصام أيام التشريق: الحادي عشر والثاني عشر والثالث عشر، ليس لأحد صومها إلا شخصاً واحداً، وهو الذي عجز عن الهدي هدي التمتع والقران فله أن يصوم هذه الثلاث في الحج وسبعة إذا رجع إلى أهله، إذا كان ما صامها قبل عرفة يصومها في هذه الثلاث؛ لأنه ثبت من حديث عائشة وابن عمر رضي الله عنهما أنهما قالا: لم يرخص في أيام التشريق أن يصمن إلا لمن لم يجد الهدي خرجه البخاري في صحيحه.\nفبينت عائشة وابن عمر رضي الله عنهما أن الرسول ﷺ رخص، إذا يقول الصحابي: (رخص) يعني، النبي ﷺ هو المرخص، في حكم المرفوع، فالذي فقد عجز عن الهدي ولم يتيسر له الهدي وهو متمتع أو قارن بين الحج والعمرة ولم يصم قبل عرفة فإنه يصوم ثلاثة أيام التي هي أيام التشريق، وسبعة إذا رجع إلى أهله.\nأما غير هذا فلا يصوم أيام التشريق، لا عن رمضان ولا عن غيره، بل يجب أن يفطر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8634/الحكمة-في-منع-الحاج-من-صيام-يوم-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31912.mp3","categories":["الوقوف بعرفة","صيام التطوع"]},{"id":10468,"question":"ما الحكمة في منع الحاج من صوم يوم عرفة؟","title":"الحكمة في منع الحجاج من صيام يوم عرفة","answer":"الجواب: الحكمة فيما بين أهل العلم أنه يوم عيد وهو يوم ينبغي فيه تعاطي ما يسبب النشاط والقوة في الدعاء والضراعة إلى الله والذكر، والصوم قد يضعفه عن ذلك، والنبي عليه السلام قال في يوم عرفة ويوم النحر، وأيام التشريق قال: عيدنا أهل الإسلام يعني: الأيام الخمسة: يوم عرفة ويوم النحر وأيام التشريق الثلاثة، قال فيها: عيدنا أهل الإسلام، وهكذا يوم الجمعة لما كانت يوم عيد نهي عن صومها مفردة، فالأفضل في يوم عرفة أن لا يصوم، ولهذا نهى النبي ﷺ عن صوم يوم عرفة بعرفة، والنبي صلى الله عليه وسلم وقف يوم عرفة مفطراً وأهدي له لبن وهو واقف بعرفة على مطيته فشرب والناس ينظرون عليه الصلاة والسلام.\nفالسنة للحجاج أن لا يصوموا يوم عرفة بل يكونوا مفطرين؛ لأنه أقوى لهم على العبادة وأنشط لهم على الخير؛ ولأنه يوم عيد، والأعياد لا تصام، لكنه يوم عيد لا يحرم صومه، وإنما يستحب الإفطار فيه، في غير الحج كأصحاب المدن والقرى، فإن السنة أن يصوموه؛ لأنه يوم فاضل يصام، لكن بالنسبة إلى الحجاج هو عيد لهم، فالأفضل لهم أن لا يصوموه، بل يقفون بعرفات وهم مفطرون كما فعل النبي عليه الصلاة والسلام، أما أهل القرى والأمصار والبوادي فالسنة لهم أن يصوموا يوم عرفة، لأنه: يوم فاضل، أخبر النبي صلى الله عليه وسلم أن صومه يكفر السنة التي قبله والتي بعده، هو يوم عظيم، لكنه في حق الحجاج عيد لهم يشرع لهم فيه الفطر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8636/الحكمة-في-منع-الحجاج-من-صيام-يوم-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32002.mp3","categories":["الوقوف بعرفة","صيام التطوع"]},{"id":10511,"question":"أحد الإخوة المستمعين يسأل سماحتكم ويقول: هل يجوز صيام الثلاثة الأيام من كل شهر متفرقة أم لابد أن تكون متتابعة؟","title":"حكم تفريق صيام الثلاثة الأيام من كل شهر وتتابعها","answer":"الجواب: مشروعة مطلقًا فرقها أو جمعها، يشرع صيام ثلاثة أيام من كل شهر سواء جمعها أو فرقها والحمد لله، وإن صامها أيام البيض فهو أفضل. نعم.","link":"https://binbaz.org.sa/fatwas/8686/حكم-تفريق-صيام-الثلاثة-الايام-من-كل-شهر-وتتابعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28219.mp3","categories":["صيام التطوع"]},{"id":10535,"question":"السائل من اليمن ومقيم بالمملكة رمز لاسمه بـ (م. س. م) يقول: سؤالي يا فضيلة الشيخ! أنا من فضل الله  علي بأنني أصوم يوم الإثنين والخميس من كل أسبوع، وإن شاء الله ناوي أصوم ثلاثة أيام من كل شهر، لكن إذا صادف الشهر يوم ثلاثة عشر يوم الخميس، وأربعة عشر يوم الجمعة، وخمسة عشر يوم السبت، هل يجوز لي أن أصوم يوم الجمعة، أفيدوني مأجورين؟","title":"حكم صوم الجمعة مع صوم يوم قبله أو بعده","answer":"الجواب: نعم، تصومه؛ لأنه تابع، المنهي عنه إفراده، أما صومه مع الخميس أو مع السبت فلا حرج فيه، نعم. والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/8710/حكم-صوم-الجمعة-مع-صوم-يوم-قبله-او-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28407.mp3","categories":["صيام التطوع"]},{"id":10844,"question":"هل يشرع تقديم صيام النفل على القضاء، كأن يصوم ستًا من شوال، ثم يقضي؟ وهل ما يؤْثَر عن عائشة أم المؤمنين -رضي الله عنها- في تأخيرها صيام القضاء إلى شعبان، صحيح أم لا؟ أفتونا مأجورين، جزاكم الله خيرًا.","title":"حكم صيام النافلة قبل قضاء صيام رمضان","answer":"الجواب:  هذه المسائل فيها خلاف بين أهل العلم، والأرجح أنه يبدأ بالقضاء؛ لقوله ﷺ: من صام رمضان، ثم أتبعه ستًا من شوال كان كصيام الدهر، وإذا كان ما صام بعض رمضان كيف يتبعه ستًا من شوال؟ عليه أن يكمل أولًا، يكمل رمضان، وعلى المرأة أن تكمل ما أفطرته من رمضان، ثم تصوم إذا أمكنها ذلك، وإلا فلا حرج والحمد لله. وقال بعض أهل العلم: إنه يبدأ بالسنن؛ لأن وقتها ضيق، قد تفوت، والقضاء وقته واسع، فلا مانع أن يبدأ بالست، أو صيام الإثنين والخميس، أو صيام يوم عرفة، أو يوم عاشوراء، والقضاء له وقت واسع، وهذا القول له وجاهة، وله حظ من النظر، ولكن القول الأول أظهر وأبين؛ لأن الفرض أهم؛ ولأن الإنسان قد يعرض له الموت والأمراض، فينبغي له أن يبدأ بالأهم، وهو القضاء، ثم إذا تيسر له بعد هذا التطوع تطوع بعد ذلك بما يسر الله. وأما خبر عائشة فهو حديث ثابت عنها -رضي الله عنها- في الصحيحين، أنها قالت: \"كان يكون علي الصوم من رمضان، فما أستطيع أن أقضيه إلا في شعبان لمكان رسول الله ﷺ\" فلا يظن بها أنها تصوم النوافل، وتؤخر الفرائض ما دام تفطر لأجل حاجة الرسول ﷺ إلى أهله، فكونها تفطر في النوافل من باب أولى. الحاصل: أنه ليس في عملها دليل على أنها كانت تصوم النوافل، لم تقل: إني كنت أصوم النوافل، بل قالت: إنها تؤخر صوم رمضان من أجل مكان الرسول ﷺ، فلا يدل على أنه ﷺ أذن لها في ذلك، أو رخص لها في ذلك، لا، بل أمر واضح في أنها أخرت من أجل مراعاة حاجة الرسول إليها -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا. وكأني بكم سماحة الشيخ تقولون: إن عائشة -رضي الله عنها- ما كانت تصوم الست من شوال في حياة الرسول ﷺ؟ الشيخ: ولا غيره من النوافل، وعليها القضاء، فالظاهر: أنها تؤخر القضاء وغير القضاء أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9025/حكم-صيام-النافلة-قبل-قضاء-صيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35606.mp3","categories":["صيام التطوع"]},{"id":11118,"question":"صيام الأيام الثلاثة من كل شهر، هل يجب أن تكون متتابعة؟","title":"حكم التتابع في صيام الأيام الثلاثة من كل شهر","answer":"الجواب:  لا يجب أن تكون لا، ولو صامها متفرقة لا بأس، إن صامها متتابعة، أو متفرقة فلا بأس، لكن إن صامها أيام البيض فهو أفضل، الثالث عشر والرابع عشر والخامس عشر، إذا صامها أيام البيض كان هذا أفضل، وإن صامها متفرقة في الشهر كله فلا بأس، الفضل حاصل، والأجر حاصل. المقدم: نعم. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9291/حكم-التتابع-في-صيام-الايام-الثلاثة-من-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36809.mp3","categories":["صيام التطوع"]},{"id":11462,"question":"ماذا على الذي يصوم شهر رجب كاملًا كما يصوم رمضان؟ وهذا السؤال من المستمع علي عثمان محمد.","title":"حكم صيام شهر رجب كاملاً","answer":"الجواب: صيام رجب مكروه؛ لأنه من سنة الجاهلية، لا يصمه، صرح كثير من أهل العلم بكراهته؛ لأن النبي ﷺ نهى عن صيام رجب. المقصود أنه من سنة الجاهلية، فلا، لكن إذا صام بعض الأيام يوم الإثنين، يوم الخميس؛ لا يضر، أو ثلاثة أيام من كل شهر؛ لا بأس، أما إذا تعمد صيامه؛ فهذا مكروه. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9643/حكم-صيام-شهر-رجب-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38117.mp3","categories":["صيام التطوع"]},{"id":11469,"question":"إذا كان الصوم نفلًا، فهل يجوز للصائم أن يفطر؟ لأدنى سبب، أو لا يجوز ذلك إلا لأسباب هامة، ومثلوا لنا جزاكم الله خيرًا.","title":"حكم الإفطار في صوم النافلة","answer":"الجواب:  إذا كان الصوم نافلة؛ فله الفطر، له الفطر مطلقًا، لكن الأفضل ألا يفطر إلا لأسباب شرعية، مثل: شدة الحر، مثل: ضيف نزل به، مثل: جماعة لزموا عليه يحضر ... زواج أو غيره يجبرهم بذلك؛ فلا بأس، النبي ﷺ: أتى بيت عائشة ذات يوم فقال: هل عندكم شيء؟ قالوا: لا. قال: فإني إذًا صائم ثم أتى في يوم آخر، فقال: هل عندكم شيء؟ قالوا: نعم. فقربوه إليه، فأكل، وقال: لقد أصبحت صائمًا فأكل -عليه الصلاة والسلام- فالأمر فيه سعة، لكن الأفضل له أن يتم الصوم إذا كان ما هناك سبب واضح، هذا الأفضل، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9650/حكم-الافطار-في-صوم-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38124.mp3","categories":["صيام التطوع"]},{"id":11583,"question":"هل يجوز صيام الست من شوال وأنا علي صيام من شهر رمضان؟ لأن لدي رغبة شديدة في ذلك، ولكن لا أستطيع القضاء؛ نظرًا لظروف معينة، منها الدراسة وما أشبه ذلك، ومنها الحياة الزوجية، وجهونا جزاكم الله خيرًا.","title":"حكم صيام الست من شوال لمن كان عليه قضاء","answer":"الجواب:  الواجب القضاء قبل الست، لا تصام الست إلا بعد القضاء؛ لقول النبي ﷺ: من صام رمضان، ثم أتبعه ستًا من شوال ومن عليه القضاء ما صام رمضان عليه بقية، والست تكون تابعة لرمضان، فالواجب القضاء ثم الست، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9766/حكم-صيام-الست-من-شوال-لمن-كان-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38612.mp3","categories":["صيام التطوع"]},{"id":11667,"question":"أرجو من سماحة الشيخ ذكر الأيام التي كان يصومها الرسول محمد ﷺ وأمر بصيامها غير فريضة رمضان، وفضلها؟","title":"الأيام التي صامها النبي عليه الصلاة والسلام وأمر بصيامها","answer":"الجواب:  كان -عليه الصلاة والسلام- يسرد الصوم في بعض الأحيان حتى يقول الصحابة: لا يفطر، وكان يسرد الإفطار حتى يقولوا: لا يصوم على حسب فراغه وشغله، فإن حصل له فراغ؛ سرد الصوم، وإن حصل له شغل؛ سرد الإفطار، عليه الصلاة والسلام. وكان يصوم الإثنين والخميس، فإذا شغل عنهما؛ صام بعد ذلك، وسرد الصوم -عليه الصلاة والسلام- وكان يحث الناس على صيام الإثنين والخميس، ويقول: إنهما يومان تعرض فيهما الأعمال على الله، فأحب أن يعرض عملي وأنا صائم، وكان يحث الناس على صيام ثلاثة أيام من كل شهر -عليه الصلاة والسلام- ويقول: الحسنة بعشر أمثالها وثلاثة أيام من كل شهر الثلاثين؛ لأنها جزء من عشرة، والحسنة بعشر أمثالها، فمن صام ثلاثة أيام من كل شهر فكأنما صام الدهر، وهكذا قال النبي ﷺ لعبدالله بن عمرو بن العاص: صم من الشهر ثلاثة أيام؛ فإن الحسنة بعشر أمثالها، وذلك صيام الدهر. ورغب الناس في صيام ست من شوال، فقال ﷺ: من صام ستًا من شوال؛ كان كصيام الدهر: من صام رمضان، ثم أتبعه ستًا من شوال؛ كان كصيام الدهر وهذا فضل من الله -جل وعلا- وقال لعبدالله بن عمرو لما طلب منه أن يسمح له بصيام الدهر قال: صم يومًا، وأفطر يومًا؛ فذلك صيام الدهر قال: وهو أفضل الصيام، وهو صوم داود عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9850/الايام-التي-صامها-النبي-عليه-الصلاة-والسلام-وامر-بصيامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29903.mp3","categories":["صيام التطوع"]},{"id":11801,"question":"من جمهورية مصر العربية محافظة الشرقية المستمع بهاء أحمدي محمد أحمد يسأل ويقول: إنني ملتزم -والحمد لله- على هذا، ومداوم على الصلاة، وأصوم الثلاثة الأيام من كل شهر، صمت أيضًا الإثنين والخميس، فتعرض لي تعب، فقطعت ذلك، هل يكون علي إثم وحالي ما ذكرت؟ جزاكم الله خيرًا.","title":"حكم من اعتاد صوم التطوع ثم عجز عنه","answer":"الجواب:  لا حرج في ذلك، صوم الإثنين والخميس، وأيام البيض كلها سنة، كلها مستحبة نافلة، من صام؛ فله أجر، ومن ترك؛ فلا شيء عليه، ولو كان يصوم، ثم ترك؛ فلا حرج عليه، حتى ولو كان صحيحًا، ليس بتعبان، من صام؛ فله أجر، ومن ترك؛ فلا شيء عليه، لكن الأفضل الاستمرار إذا تيسر له ذلك، الأفضل الاستمرار، والدوام على الخير، وإلا فلا حرج إذا أفطر بعض الأيام، ولم يصم، أو أفطر بعض أيام البيضـ ولم يصمها، أو صام في غير أيام البيض، وهكذا ست من شوال لو كان يصومها، ثم ترك؛ فلا حرج. المقصود: أنها نوافل.. أنها نوافل من شاء صام، وهو أفضل، وله أجر، ومن أفطر؛ فلا حرج عليه، وإن كان صحيحًا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9985/حكم-من-اعتاد-صوم-التطوع-ثم-عجز-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42303.mp3","categories":["صيام التطوع"]},{"id":11828,"question":"أحد الإخوة من اليمن اسمه خادم علي، بعث يسأل سماحتكم ويقول: إنني في رمضان مضت علي يومان كنت مريضًا وبعد رمضان لم أقض، بل صمت الست من شوال، وأريد بعد صيام الست أن أقضي ذلكم الصيام الذي فاتني، فما حكم ما فعلت؟ جزاكم الله خيرًا.","title":"قضاء الصوم المفروض يقدم على التطوع","answer":"الجواب:  المشروع لك أن تقدم صيام اليومين قبل الست، لكن لما جهلت هذا تصومهما بعد ذلك والحمد لله، ولا شيء عليك إذا صمتهما قبل رمضان، فإن أخرتهما إلى رمضان الآخر؛ فعليك مع الصيام إطعام مسكين، عن كل يوم صاع عن اليومين، عن كل يوم نص صاع، تعطيه بعض الفقراء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10019/قضاء-الصوم-المفروض-يقدم-على-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39522.mp3","categories":["صيام التطوع"]},{"id":11949,"question":"من كان معتادًا لصوم الإثنين والخميس، فأفطر أحد هذه الأيام، هل يلزمه القضاء؟","title":"حكم من اعتاد صيام الإثنين والخميس فأفطر في أحدهما","answer":"الجواب:  ليس عليه قضاء؛ لأنه نافلة ....، إذا كان يعتاد صوم الإثنين والخميس، وأفطر في بعض الأحيان؛ فلا قضاء عليه، الأمر واسع بحمد الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10134/حكم-من-اعتاد-صيام-الاثنين-والخميس-فافطر-في-احدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42813.mp3","categories":["صيام التطوع"]},{"id":11988,"question":"يسأل أيضًا ويقول: حدثونا عن صوم التطوع، مع بيان الأهم فالمهم من صوم التطوع، جزاكم الله خيرًا؟","title":"صوم التطوع والأيام التي يستحب صيامها","answer":"الجواب:  صوم التطوع سنة، قربة عظيمة، جاء في بعض الأحاديث عن أبي ذر ، أن النبي  قال لأبي ذر : عليك بالصوم؛ فإنه لا مثل له. فالصوم له شأن عظيم، فينبغي للمؤمن أن يكثر من الصيام، وفي الحديث الصحيح يقول الله -جل وعلا-:  كل عمل ابن آدم له، الحسنة بعشر أمثالها يقول الله  إلا الصيام فإنه لي، وأنا أجزي به، ترك شهوته وطعامه وشرابه من أجلي، للصائم فرحتان: فرحة عند فطره، وفرحة عند لقاء ربه، ولخلوف فم الصائم أطيب عند الله من ريح المسك هذا يعم الفرض والنفل. فالصوم له شأن، يستحب الإكثار منه، وأفضله أن تصوم يومًا وتفطر يومًا، هذا أحسنه، كما أرشد النبي ﷺ عبدالله بن عمرو إلى ذلك، وقال: إنه صوم داود، وإنه أفضل الصيام شطر الدهر، يصوم يومًا ويفطر يومًا وإن شاء صام الإثنين والخميس، كان النبي ﷺ يصومهما، ويقول: إنهما يومان تعرض فيهما الأعمال على الله، فأحب أن يعرض عملي وأنا صائم فيستحب صيام الإثنين والخميس، وهكذا صيام ثلاثة أيام من كل شهر مستحبة، كان النبي ﷺ يأمر بذلك، وأوصى بعض أصحابه بصيام ثلاثة أيام من كل شهر، وهي صيام الدهر؛ لأن الحسنة بعشر أمثالها، والشهر ثلاثون، أو تسعة وعشرون، فإذا صام ثلاثة؛ قد صام الدهر، الحسنة بعشر أمثالها. فينبغي للمؤمن أن يتحرى الصوم على أحد هذه الوجوه، صيام التطوع. ويستحب صيام ست من شوال متتابعة، أو مفرقة، وصوم يوم عرفة لمن ليس حاجًا، صوم عاشوراء العاشر من المحرم، ويصوم معه يومًا قبله، أو يومًا بعده، أو كلاهما، كل هذه مستحبة، ويوم عرفة يكفر الله به السنة التي قبله، والسنة التي بعده، ويوم عاشوراء صومه يكفر السنة التي قبله، لكن الحاج لا يصوم يوم عرفة، النبي ﷺ حج، ولم يصم يوم عرفة، لكن في غير الحج يصوم، هذه هي أنواع صوم التطوع، أفضلها أن يصوم يومًا، ويفطر يومًا، وهذا صوم داود -عليه الصلاة والسلام- شطر الدهر، والبقية فيها خير عظيم، إن شاء صام ثلاثة أيام من كل شهر، ويكفي، وإن شاء صام الإثنين والخميس، كل هذا مستحب. وهناك أيام مخصوصة من ذلك صوم عرفة، صوم عاشوراء يصوم معه يومًا قبله، أو بعده، أو يصوم قبله وبعده جميعًا ثلاثة أيام، فيصير الجميع ثلاثة أيام، صوم ستة أيام من شوال كذلك سنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10173/صوم-التطوع-والايام-التي-يستحب-صيامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43102.mp3","categories":["صيام التطوع"]},{"id":12005,"question":"المستمع: حازم الجهيران بعث يسأل ويقول: أيهما أفضل، صيام الإثنين والخميس من كل شهر، أم صيام الثلاثة الأيام؟ وهل يعوض صيام الإثنين والخميس عن الثلاثة الأيام؟","title":"أيهما أفضل، صيام الإثنين والخميس، أم صيام الثلاثة الأيام؟","answer":"الجواب:  نعم، إذا صام الإثنين والخميس أفضل؛ لأن هذا أكثر خيرًا، ويقومان مقام ثلاثة الأيام من كل شهر من باب أولى، وإن صام ثلاثة أيام؛ كفى، فالحمد لله، كله خير، كله نافلة، لكن الإثنين والخميس أكثر أجرًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10190/ايهما-افضل-صيام-الاثنين-والخميس-ام-صيام-الثلاثة-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43119.mp3","categories":["صيام التطوع"]},{"id":12067,"question":"يسأل سماحتكم ويقول: أفتوني عن الأيام التي يشرع صيامها صيام التطوع، وأخبروني بالأهمية حيث أعرف الأهم فالأهم، جزاكم الله خيرًا.","title":"الأيام التي يستحب صيامها تطوعاً","answer":"الجواب: الأفضل للمؤمن أن يصوم ثلاثة أيام من كل شهر، كونه يصوم ثلاثة أيام من كل شهر؛ لأن الرسول ﷺ أمر بذلك عبدالله بن عمرو وغيره، وأوصى أبا هريرة وأبا الدرداء بذلك.. صيام ثلاثة أيام من كل شهر، وإذا صامها أيام البيض كان أفضل، وهي اليوم الثالث عشر، والرابع عشر، والخامس عشر، وإن صامها في غير ذلك؛ فلا بأس. المقصود: أن يصوم ثلاثة أيام من كل شهر، في أوله، أو في وسطه، أو في آخره، مفرقة أو مجتمعة، كله لا بأس به، إن صامها في أيام البيض؛ فذلك أفضل، يلي ذلك أن يصوم الإثنين والخميس، يستحب صيام الإثنين والخميس، وكان النبي يصومهما، عليه الصلاة والسلام. ثم يلي ذلك صيام يوم، وفطر يوم، وهذا أفضلها، أفضل شيء إذا قدر أن يصوم يومًا ويفطر يومًا، هذا أفضل التطوع، قاله النبي ﷺ لـعبدالله بن عمرو: صم يومًا، وأفطر يومًا؛ فذلك صيام داود، وهو أفضل الصيام. لكن إذا صام الإنسان ثلاثة أيام من كل شهر، ولم يكلف نفسه؛ كان أرفق به، أو صام الإثنين والخميس؛ كان أرفق به، ويستحب صيام ست من شوال من الفطر الأول، يصومها الإنسان كل سنة، هذا أفضل ستًا من شوال مجتمعة، أو متفرقة، ويستحب الصيام يوم عرفة تسع ذي الحجة؛ لأنها أيام عظيمة، وهكذا صيام يوم عاشوراء، العاشر من المحرم، ويستحب أن يصوم قبله يومًا، أو بعده يومًا، أو يصوم اليوم الذي قبله والذي بعده، كل هذه مستحبة، لكن أفضلها أن يصوم يومًا ويفطر يومًا إذا قدر وتيسر، نعم.","link":"https://binbaz.org.sa/fatwas/10252/الايام-التي-يستحب-صيامها-تطوعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43416.mp3","categories":["صيام التطوع"]},{"id":12254,"question":"إذا كان شخص يداوم على صيام بعض النوافل، كالإثنين والخميس، أو ستةٍ من شوال، فهل يجوز له أن يتركها، ثم يصومها، وهكذا، أم أنه ملزم بها؟ نرجو التوجيه، جزاكم الله خيرًا.","title":"حكم ترك الصيام أحيانا للنوافل التي كانت تصام","answer":"الجواب:  هذه نوافل، لا يلزمه الاستمرار فيها، إذا تيسر له صام، وإذا شق عليه ترك، كان النبي ﷺ يصوم تارة ويترك أخرى -عليه الصلاة والسلام- إذا حصل له الفراغ سرد الصوم، وإذا شغل سرد الإفطار -عليه الصلاة والسلام- فإذا كان يصوم الإثنين والخميس، أو ستًا من شوال، أو يصوم يومًا، ويفطر يومًا، فهو يفعل ذلك إذا تيسر له ذلك، وإذا ترك؛ فلا حرج؛ لأنها نافلة، ليست واجبة، يفعلها متى نشط، ومتى ثقل عليه ذلك، أو كسل عن ذلك؛ فلا حرج في ذلك، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10454/حكم-ترك-الصيام-احيانا-للنوافل-التي-كانت-تصام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44905.mp3","categories":["صيام التطوع"]},{"id":12281,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من اليمن الجنوبي بتوقيع إحدى الأخوات المستمعات من هناك تقول: أم أيمن، أم أيمن لها ثمانية أسئلة في أحدها تقول: امرأة نذرت أن تصوم ستًا من شوال من كل عام، هل تصوم النذر أولًا، أم تقضي ما أفطرته في رمضان لحيضها أو نفاسها؟ وماذا لو كان صيام الست من شوال تطوعًا؟ هل تقضي أولًا، أم تصوم التطوع؟","title":"تقديم قضاء صوم رمضان على صوم النذر والتطوع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالأفضل لها أن تقدم القضاء، ثم تصوم الست بعد ذلك، سواء كانت الست عن نذر، أو تطوعًا حتى تكمل رمضان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10481/تقديم-قضاء-صوم-رمضان-على-صوم-النذر-والتطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45201.mp3","categories":["صيام التطوع"]},{"id":12337,"question":"تقول: حدث أن صمت في العشرة الأيام الأولى من شهر ذي الحجة تطوعًا، وأنا علي دين من أيام رمضان، فهل يجوز قضاء أيام شهر من رمضان في الأيام الأولى من شهر ذي الحجة؟","title":"حكم صوم النافلة قبل صيام القضاء","answer":"الجواب:  نعم، الواجب على من عليه دين أن يبدأ به قبل التطوع، في شهر ذي الحجة، أو في غيره، وهكذا ست من شوال، لا يصمها من عليه قضاء، يقدم القضاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10549/حكم-صوم-النافلة-قبل-صيام-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39908.mp3","categories":["صيام التطوع"]},{"id":12408,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (ب. س) من الرياض تسأل وتقول: ورد في الحديث أن من جلس بعد صلاة الفجر إلى طلوع الشمس على مصلاه يذكر الله حتى يصلي ركعتي الفجر؛ كتبت له أجر حجة وعمرة، وقال أهل العلم: إن المرأة إذا فعلت ذلك في بيتها يرجى لها نصف الأجر،  هناك أناس يقولون: إنه يشترط لهذه الجلسة ألا يتحدث مع أحد في أمور الدنيا، هل هذا الكلام صحيح، وإذا كان صحيحًا، فماذا أفعل إذا كانت والدتي كبيرة في السن، وقد أخبرتها بذلك، ولكنها تنسى، وتحدثني بأمور دنيوية، لا ضرورة لها خلال جلستي هذه، فهل إذا جلست مبتغيةً الثواب من الله، ولكن تحدثت مع أمي، وأجبتها حرصًا على رضاها، هل أكون قد أديت العبادة كما ينبغي؟","title":"هل تدخل المرأة في فضل الجلوس بعد الفجر إلى الإشراق؟","answer":"الجواب:  نعم نعم جمعت بين الخيرين، بين الذكر، وبين رضا الوالدة، وبرها من أهم المهمات، فالحديث معها إذا طلبت الحديث أمر مطلوب، ومشروع، ولا يضر، ولا يقطع الجلسة، ولا يؤثر عليك، فمن جلس في مصلاه يذكر الله، يصلي على النبي ﷺ ويسبح، ويدعو حتى تطلع الشمس، ثم يصلي ركعتين سنة الضحى، هاتان الركعتان يقال لها: سنة الضحى، ويسميها العامة سنة الإشراق، وهي سنة الضحى مبكرة، فله أجر، جاء في الحديث: أجر حجة وعمرة تامتين. ولا فرق بين الرجال والنساء، المرأة كالرجل ما هو النصف، نصف حجة، لا حجة تامة، الرجل والمرأة سواء في هذا، الحديث عام للرجال والنساء، فالمرأة في بيتها تجلس في مصلاها، والرجل في مصلاه في المسجد حتى تطلع الشمس، ثم يصلي ركعتين، هذا كله خير عظيم، يشتغل بذكر الله، بالدعاء، بقراءة القرآن، الحمد لله، وإذا تكلم مع أخيه في شيء دعت إليه الحاجة؛ فلا بأس، أو تكلمت المرأة مع زوجها، أو مع والدتها، أو مع غيرهم في الحاجة؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الذين قالوا: إن المرأة لها نصف الأجر ليسوا على صواب؟ الشيخ: غلط، لا الأجر عام، الحكم واحد، فالرجل والمرأة سواء. المقدم: بارك الله فيكم، وسواء كان ذلك في المسجد، أو في بيتها. الشيخ: نعم نعم في المسجد، أو في البيت. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10620/هل-تدخل-المراة-في-فضل-الجلوس-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40208.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":12415,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (ب. س) من الرياض تسأل وتقول: ورد في الحديث أن من جلس بعد صلاة الفجر إلى طلوع الشمس على مصلاه يذكر الله حتى يصلي ركعتي الفجر؛ كتبت له أجر حجة وعمرة، وقال أهل العلم: إن المرأة إذا فعلت ذلك في بيتها يرجى لها نصف الأجر،  هناك أناس يقولون: إنه يشترط لهذه الجلسة ألا يتحدث مع أحد في أمور الدنيا، هل هذا الكلام صحيح، وإذا كان صحيحًا، فماذا أفعل إذا كانت والدتي كبيرة في السن، وقد أخبرتها بذلك، ولكنها تنسى، وتحدثني بأمور دنيوية، لا ضرورة لها خلال جلستي هذه، فهل إذا جلست مبتغيةً الثواب من الله، ولكن تحدثت مع أمي، وأجبتها حرصًا على رضاها، هل أكون قد أديت العبادة كما ينبغي؟","title":"هل تدخل المرأة في فضل الجلوس بعد الفجر إلى الإشراق؟","answer":"الجواب:  نعم نعم جمعت بين الخيرين، بين الذكر، وبين رضا الوالدة، وبرها من أهم المهمات، فالحديث معها إذا طلبت الحديث أمر مطلوب، ومشروع، ولا يضر، ولا يقطع الجلسة، ولا يؤثر عليك، فمن جلس في مصلاه يذكر الله، يصلي على النبي ﷺ ويسبح، ويدعو حتى تطلع الشمس، ثم يصلي ركعتين سنة الضحى، هاتان الركعتان يقال لها: سنة الضحى، ويسميها العامة سنة الإشراق، وهي سنة الضحى مبكرة، فله أجر، جاء في الحديث: أجر حجة وعمرة تامتين. ولا فرق بين الرجال والنساء، المرأة كالرجل ما هو النصف، نصف حجة، لا حجة تامة، الرجل والمرأة سواء في هذا، الحديث عام للرجال والنساء، فالمرأة في بيتها تجلس في مصلاها، والرجل في مصلاه في المسجد حتى تطلع الشمس، ثم يصلي ركعتين، هذا كله خير عظيم، يشتغل بذكر الله، بالدعاء، بقراءة القرآن، الحمد لله، وإذا تكلم مع أخيه في شيء دعت إليه الحاجة؛ فلا بأس، أو تكلمت المرأة مع زوجها، أو مع والدتها، أو مع غيرهم في الحاجة؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الذين قالوا: إن المرأة لها نصف الأجر ليسوا على صواب؟ الشيخ: غلط، لا الأجر عام، الحكم واحد، فالرجل والمرأة سواء. المقدم: بارك الله فيكم، وسواء كان ذلك في المسجد، أو في بيتها. الشيخ: نعم نعم في المسجد، أو في البيت. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10620/هل-تدخل-المراة-في-فضل-الجلوس-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40208.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":12581,"question":"إذا قال رجل: إني -إن شاء الله- سأصوم يومًا، علمًا بأن هذا اليوم هو يوم الإثنين، فنسي أن يصوم، ماذا عليه؟","title":"حكم من علق صوم يوم معين على المشيئة فنسي","answer":"الجواب:  ليس عليه شيء؛ لأن هذا لا يسمى نذرًا، هذا وعد معلق بالمشيئة، فلم يشأ الله له ذلك، إذا قال: إن شاء الله أصوم يوم الخميس، إن شاء الله أصوم يوم الإثنين، إن شاء الله أزور فلانًا، إن شاء الله أحج، إن شاء الله أصلي الضحى، كل هذا لا شيء عليه إذا لم يفعل ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/10785/حكم-من-علق-صوم-يوم-معين-على-المشيىة-فنسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41202.mp3","categories":["صيام التطوع"]},{"id":12794,"question":"رسالة وصلت إلى البرنامج من المستمع (أ. ن. ج. البياتي) يقول في أحد أسئلته: هل يجوز للمسلم أن يصوم أيام السنة كاملة، أم أن ذلك بدعة؟ جزاكم الله خيرًا.","title":"حكم صيام الدهر","answer":"الجواب:  لا ينبغي أن يصوم، النبي ﷺ قال: لا صام ولا أفطر لا صام من صام الأبد فأقل أحواله الكراهة الشديدة، فلا ينبغي له أن يصوم الأبد، أفضل ذلك يوم، يوم يصوم ويوم يفطر، هذا هو الأفضل، يصوم يومًا، ويفطر يومًا، قال النبي ﷺ: هذا أفضل الصيام وهو صوم داود نبي الله -عليه الصلاة والسلام- وإن صام الإثنين والخميس؛ كفى، أو صام ثلاثة أيام من كل شهر؛ يكون طيبًا، وإن لم يصم؛ فلا حرج عليه، لا يجب عليه إلا رمضان إلا أن تجب عليه كفارة، أو نذر، هذا مستثنى، وإلا فليس عليه شيء واجب بأصل الشرع إلا رمضان، ومن أحب أن يصوم الإثنين، أو الخميس، أو ستًا من شوال، أو يصوم يومًا، ويفطر يومًا؛ فهذا كله طيب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11008/حكم-صيام-الدهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46114.mp3","categories":["صيام التطوع"]},{"id":12970,"question":"هذه السائلة من سوريا -أم عبدالرحمن- تقول في هذا  فضيلة الشيخ، هل الصيام بعد خمسة عشر من شعبان حرامٌ، أو مكروهٌ؟ نرجو منكم الإفادة.","title":"حكم الصيام بعد منتصف شعبان","answer":"الجواب:  يقول النبي ﷺ: إذا انتصف شعبان فلا تصوموا وهو حديثٌ صحيحٌ، فالذي ما صام أول الشهر ليس له أن يصوم بعد النصف؛ لهذا الحديث الصحيح، وهكذا لو صام آخر الشهر ليس له ذلك من باب أولى؛ لقوله ﷺ: لا تقدموا رمضان بصوم يومٍ، ولا يومين إلا رجلٌ كان يصوم صومًا؛ فليصمه الذي له عادةٌ؛ لا بأس، إذا كانت عادته أن يصوم الاثنين والخميس؛ فلا بأس أن يصوم، أو عادته أن يصوم يومًا، ويُفطر يومًا، لا بأس، أما أن يبتدئ الصيام بعد النصف من أجل شعبان؛ هذا لا يجوز. أما لو صام بدءًا من أربعة عشر، أو من خمسة عشر، أو من ثلاثة عشر، أو ... فلا بأس؛ لأنه أكثره، إذا صام كله، أو أكثره فلا بأس، أما كونه يُفطر النصف الأول، ثم يبتدئ هذا هو المنهي عنه. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11186/حكم-الصيام-بعد-منتصف-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50303.mp3","categories":["صيام التطوع"]},{"id":13188,"question":"تقول: يوجد عندنا من يصوم عشرة أيام من الشهر مثلًا: يصومون ثلاثة أيام في بداية الشهر، وثلاثة أيام في نصف الشهر، وثلاثة أيام في آخر الشهر، ويقولون: إنه مستحب، صيام هذه الأيام ولي جدة تحافظ على هذا العمل، ما رأيكم جزاكم الله خيرًا؟","title":"حكم صيام ثلاثة أيام من بداية ووسط وآخر الشهر","answer":"الجواب:  ما نعلم لهذا أصلًا، لكن الصيام مشروع، وأما كونه يحافظ على ثلاث، ثم ثلاث، ثم ثلاث ما نعرف له أصلًا، النبي ﷺ قال لعبد الله بن عمرو وغيره: صم من الشهر ثلاثة أيام تكفي، وأوصى أبا هريرة وأبا الدرداء بصيام ثلاثة أيام من كل شهر. فالأفضل الاكتفاء بثلاثة أيام، فإن شاء نشط وصام أكثر فلا بأس، أو صام الإثنين والخميس، أو صام خمسة أيام من كل شهر، أو نحو ذلك لا بأس، لكن الأفضل أن يصوم الإثنين والخميس أو ثلاثة أيام من كل شهر، أما استمراره على ثلاثة، ثم ثلاثة، ثم ثلاثة يعتقد أنها سنة فلا أعلم لهذا أصلًا، لكن لو صام خمسة عشر، وأفطر خمسة عشر، يعني: النص؛ فلا بأس، فإن أفضل الصيام أن يصوم يومًا ويفطر يومًا، فإذا صام نصف الشهر، وأفطر نصفه، أو صام يومًا وأفطر يومًا، أو صام يومًا وأفطر يومين، فكل هذا لا بأس به، أرشد إليه النبي -عليه الصلاة والسلام- اللهم صل عليه، نعم.","link":"https://binbaz.org.sa/fatwas/11443/حكم-صيام-ثلاثة-ايام-من-بداية-ووسط-واخر-الشهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47505.mp3","categories":["صيام التطوع"]},{"id":13334,"question":"هذه السائلة (ن.ع. م) من الأردن لها مجموعة من الأسئلة، تقول في السؤال الأول: سماحة الشيخ! ما حكم صيام يوم السبت؟ حيث إنني قد سمعت آراء كثيرة في صيام هذا اليوم، فمن الناس من يقول: إنه لا يصام إلا إذا سبق بيوم، وألحق بيوم صيام، ومنهم من يقول: إنه لا يجوز أن يصام هذا أبدًا إلا إذا كان صيام فرض، أما تطوع فلا، وإذا كان كذلك، وأردت أن أصوم صيام داود  فلابد من مرور يوم السبت للصيام فيه، دون أن أسبقه بيوم صيام، أو أن ألحقه بيوم صيام، فما هو رأيكم في ذلك؟","title":"حكم صيام يوم السبت","answer":"الجواب:  الحديث في النهي عن صوم يوم السبت... حديث ضعيف شاذ مضطرب، وهو ما يروى عنه ﷺ أنه قال: لا يصومن أحد يوم السبت إلا فيما افترض عليه، فإن لم يجد إلا لحاء عنب، أو عود شجرة؛ فليمضغ هذا الحديث ضعيف، ومضطرب نبه عليه الحفاظ. فالحديث غير صحيح، فلا بأس بصوم يوم السبت مع الجمعة، أو مع الأحد، أو مفردًا، لا حرج فيه، هذا هو الصواب، وهذا هو الصحيح، والحديث ضعيف، لا يصح الاحتجاج به. ومما يدل على ضعفه ما ثبت في الصحيحين عن النبي ﷺ أنه قال: لا يصومن أحد يوم الجمعة إلا أن يصوم يومًا قبله، أو يومًا بعده فأباح للناس أن يصوموا يومًا بعده... بعد الجمعة وهو السبت في النافلة، فدل على أن الحديث الذي فيه النهي عن صومه إلا في الفريضة حديث باطل، مخالف للأحاديث الصحيحة. وهكذا كان -عليه الصلاة والسلام- يصوم يوم الأحد، ويوم السبت ويقول: إنهما يوما عيد للمشركين، فأنا أريد أن أخالفهم.  والخلاصة: أن الحديث في النهي عن صوم السبت حديث ضعيف، بل باطل غير صحيح، ولا حرج في صوم يوم السبت مفردًا، أو مع الجمعة، أو مع الأحد، كل ذلك لا بأس به، والحمد لله. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11620/حكم-صيام-يوم-السبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54204.mp3","categories":["صيام التطوع"]},{"id":13446,"question":"بعد ذلك ننتقل إلى سؤال، السائل: حلمي إسماعيل، يقول في هذا  صمت يوم عاشوراء، أي: يوم العاشر والحادي عشر؛ لأن مكان عملي في الشمس، ولم أستطع أن أصوم يوم التاسع، وصمت العاشر والحادي عشر؛ لأنه كان يوافق يوم الجمعة، فهل صيامي صحيح، أفيدوني سماحة الشيخ؟","title":"حكم صيام يوم عاشوراء مع يوم بعده","answer":"الجواب: لا حرج في ذلك، نعم، السنة أن يصوم العاشر، ويصوم معه التاسع، أو الحادي عشر، فإذا صام الحادي عشر مع العاشر فالحمد لله، وقد جاء عنه ﷺ أنه قال: صوموا يومًا قبله، أو يومًا بعده، فأنت على خير، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/11745/حكم-صيام-يوم-عاشوراء-مع-يوم-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51614.mp3","categories":["صيام التطوع"]},{"id":13544,"question":"تسأل أختنا وتقول: هل يجوز للمرأة أن تصوم ستًا من شوال قبل أن تقضي الأيام التي أفطرتها في رمضان لعذر شرعي مثلًا؟","title":"حكم صيام ست من شوال لمن عليه قضاء","answer":"الجواب: اختلف العلماء في هذه المسألة منهم من أجاز أن تصوم الست قبل قضاء الواجب، ومنهم من لم يجز ذلك، والأحوط للمؤمن والمؤمنة أن يبدأ بالقضاء، الذي عليه قضاء يبدأ به قبل الست، هذا هو الأحوط، وهذا هو الذي ينبغي؛ لأن الواجب أهم من النافلة، فالتي عليها قضاء تبدأ بالقضاء، ثم تصوم إن تيسر لها ذلك، وإلا فالقضاء أهم، وهكذا الرجل الذي عليه قضاء بسبب مرض، أو سفر يبدأ بالقضاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11864/حكم-صيام-ست-من-شوال-لمن-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48002.mp3","categories":["صيام التطوع"]},{"id":13729,"question":"هل يجوز صيام ليلة النصف من شعبان، وقيام ليلة النصف أيضًا؟","title":"حكم صيام يوم النصف من شعبان وقيام ليلته","answer":"الجواب: ليس عليه دليل، كل الأحاديث التي في هذا ضعيفة، فلا يشرع له صيام يوم النصف، ولا قيام ليلة النصف، كل الأحاديث ضعيفة التي في هذا الباب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12100/حكم-صيام-يوم-النصف-من-شعبان-وقيام-ليلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48114.mp3","categories":["صيام التطوع","البدع والمحدثات"]},{"id":13766,"question":"هل صيام النافلة يحتاج إلى تبييت النية؟ أم أنه بإمكان الإنسان أن ينوي الصيام في أي وقت من أي يوم إذا لم يتناول شيئًا بعد أذان الفجر؟","title":"حكم تبييت النية في صيام النافلة","answer":"الجواب: لا بأس بهذا، ليس بشرط تبييت النية في النافلة، لو أصبح ولم يأكل شيئًا ولم يتعاط مفطرًا فله أن يصوم النافلة كما في الحديث الصحيح: أن الرسول ﷺ دخل على عائشة ذات يوم فقال: هل عندكم شيء؟ قالت: لا، قال: فإني إذًا صائم. فالصوم من أثناء النهار لا بأس إذا كان ما تعاطى مفطرات، أما الفريضة لا بد من تبييت النية؛ لقوله ﷺ: من لم يبيت الصيام من الليل فلا صوم له، إذا كان فريضة رمضان أو كفارة أو نذر، لا بد أن يبيت النية، يعني: ينوي قبل طلوع الفجر. نعم.","link":"https://binbaz.org.sa/fatwas/12156/حكم-تبييت-النية-في-صيام-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53609.mp3","categories":["صيام التطوع"]},{"id":13914,"question":"تقول السائلة من الجزائر سؤالي عن صيام التطوع، فكما هو معروف عندنا بأن من صام هذه الستة أيام من شوال تبقى عليه دين؛ أي يجب عليه أن يصومها في كل عام حتى الممات، ويجب عليه أيضًا أن يصوم بقية أيام التطوع وهي يوم عرفة، والأيام البيض من كل شهر، والنصف الثاني من شعبان وعاشوراء.. إلى غير ذلك من الأيام الأخرى، فهل هذا صحيح؟","title":"هل من صام نافلة تجب عليه بعد ذلك؟","answer":"الجواب: ليس هذا بصحيح، النوافل من شاء فعل ومن شاء ترك، هذه مستحبة نافلة، إن شاء صامها كل سنة وإن شاء صامها بعض السنين وتركها بعض السنين، الأمر في هذا واسع، وهكذا صوم عرفة، وهكذا صوم يوم عاشوراء، وهكذا صوم الإثنين والخميس، وصيام ثلاثة أيام من كل شهر.. كلها نافلة، إذا يسر الله له الصوم صامها، وإذا تركها فلا حرج، وإذا صام في بعض الشهور وترك في بعض الشهور لا بأس، وكان النبي ﷺ ربما صام، وربما ترك، ربما صام الأيام الثلاثة من كل شهر، وربما صام الإثنين والخميس، وربما شغل عن هذا وترك ولم يصم عليه الصلاة والسلام.\nوهكذا شعبان، كان يصومه في الغالب كله أو إلا قليلاً كما قالت عائشة وأم سلمة، فإذا تيسر الصوم فلا بأس وإلا فلا حرج، إنما هذا في الفريضة.. الفريضة لابد منها.. صوم رمضان لابد منه إلا من علة كالمرض والسفر، أما النوافل فالحمد لله الأمر فيها واسع، إذا صامها بعض السنين وتركها بعض السنين لا بأس، أو صام ثلاثة أيام من كل شهر بعض الأحيان وترك، أو صام الإثنين والخميس في بعض الأحيان وترك كل هذا لا حرج فيه والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12311/هل-من-صام-نافلة-تجب-عليه-بعد-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54403.mp3","categories":["صيام التطوع"]},{"id":14450,"question":"السائلة التي أرسلت بهذه المجموعة من الأسئلة من جازان السائلة (ف. ع) تقول في هذا  سماحة الشيخ، ما حكم صيام يوم الإثنين والخميس بنية تكفير ما كان علي من ذنوب سبقت أيام ما كنت في غفلة من الله ، وهل يغفر الله  ذنوبي حتى لو كانت كبيرة وفعلتها متعمدة، ولكنني الآن تبت إلى الله ، وندمت على ما فعلت؟وجهوني سماحة الشيخ.","title":"ما حكم صيام التطوع بنية تكفير السيئات؟","answer":"الجواب: التوبة يمحو الله بها الذنوب، التوبة الصادقة النصوح يمحو الله بها الذنوب، إذا كنت تبت عن ندم وإقلاع وصدق وإخلاص الحمد لله، ولكن الصوم ينفع؛ لأن الحسنات يذهبن السيئات، كما قال تعالى: إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ [هود:114] والحسنة بعشر أمثالها إلى سبعمائة ضعف كما قال تعالى: مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا [الأنعام:160]. فاستكثري من الصوم، ومن الصلاة النافلة، ومن الصدقات والتسبيح والتهليل والتحميد والذكر والاستغفار كل هذه ينفع المسلم، ولو كان من أصلح الناس ينفعه ذلك، فكيف إذا كان قد أسلف سيئة؟ هذا مما يرفعه الله به درجات، ومما يزيده به خيرًا، فاستكثري من الخير، والتوبة تجب ما قبلها والحمد لله، ولكن كون الإنسان يصوم الإثنين والخميس، أو يصوم ثلاثة أيام من كل شهر، أو يتصدق كثيرًا، أو يسبح ويكبر، كل هذا مما يرفعه الله به درجات، ويضاعف به أجره، وله فيه خير كثير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12918/ما-حكم-صيام-التطوع-بنية-تكفير-السيىات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55408.mp3","categories":["صيام التطوع"]},{"id":14675,"question":"إحدى الأخوات المستمعات بعثت برسالة هي سامية محمد تقول: قرأت في كتابين قولًا مختلفًا عن صوم يومي الإثنين والخميس، وجهوني حول هذا الموضوع. جزاكم الله خيرًا.","title":"حكم صوم يومي الإثنين والخميس","answer":"الجواب: صوم الإثنين والخميس سنة، كان النبي يفعل ذلك -عليه الصلاة والسلام-، وسئل عن ذلك فقال: إنهما يومان تعرض فيهما الأعمال على الله، فأحب أن يعرض عملي وأنا صائم فالسنة للمؤمن والمؤمنة صومهما إذا تيسر ذلك، لكن ليس ذلك بواجب إنما هو مستحب. وهكذا صيام ثلاثة أيام من كل شهر، وصيام أيام البيض -وهي: الثالث عشر والرابع عشر والخامس عشر- كله سنة، فإذا صام أيام البيض، أو صام ثلاثة أيام من أول الشهر، أو من وسطه أو من آخره أو فرقها كل ذلك سنة، أو صام الإثنين والخميس كله سنة، نعم. المقدم: جزاكم الله خيرًا، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13180/حكم-صوم-يومي-الاثنين-والخميس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62807.mp3","categories":["صيام التطوع"]},{"id":14680,"question":"أيضًا تكرموا واشرحوا لنا هذا الحديث: عن أبي أيوب  أن رسول الله ﷺ قال: من صام رمضان ثم أتبعه ستًا من شوال كان كصيام الدهر أرجو أن تتفضلوا ببيان هذه الأيام، هل هي في أول الشهر أو في وسطه أو في آخره؟","title":"وقت صوم ست من شوال وحكم تقديمها على القضاء","answer":"الجواب: الحديث صحيح، رواه مسلم في الصحيح، وله شواهد، كلها تدل على أنه يستحب للمؤمن والمؤمنة صيام ست أيام من شوال، إذا أفطر من رمضان يستحب له أن يصوم ستًا من شوال.  والنبي ﷺ لم يحدد هل تكون في أوله أو في آخره أو في وسطه، فدل ذلك على أن الأمر واسع، ولا حرج في صومها في أوله أو في وسطه أو في آخره، ولا حرج أيضًا في صومها متتابعة أو متفرقة كل ذلك واسع، والحمد لله. لكن إذا بادر بها خشية القواطع والعوائق فهو حسن، كما قال الله -جل وعلا-: وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَى [طه:84] قال سبحانه: سَابِقُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ [الحديد:21] الآية، قال: فَاسْتَبِقُوا الْخَيْرَاتِ [البقرة:148] فإذا سابق إليها الإنسان وصامها من أول الشهر متتابعة خشية أن يعوق عائق، أو يحدث ما يمنعه فهذا من باب الحيطة، ومن باب المسابقة إلى الخير، ومن باب الحزم في فعل الخيرات، وإن أخرها في وسط الشهر أو في آخر الشهر فلا حرج، أو صامها متفرقة صام وأفطر حتى كمل الست فلا حرج في ذلك كله، والحمد لله.\nالمقدم: جزاكم الله خيرًا. من أفطر لعذر سماحة الشيخ، هل يبدأ بقضاء ما فاته من صيام رمضان، أو يبدأ بصيام الست؟ الشيخ: الأفضل أن يبدأ بالصيام الذي قضاء الذي عليه؛ لأنه هو الفرض، والناس اختلفوا في هذا، بعض أهل العلم قال: لا بد من البدأة بالقضاء.  وبعض أهل العلم قال: يجوز تأخير القضاء وفعل المستحبات، وبعضهم أجاز تقديم المستحبات لكن فضل القضاء، وهذا هو الذي ينبغي يفضل القضاء، يعني: ينبغي له أن يبدأ بالقضاء، لكن لو صام مثل يوم عرفة وعليه قضاء، أو صام يوم عاشوراء وعليه قضاء، أو صام ثلاثة أيام من كل شهر وعليه قضاء، فإنه يجزئه -إن شاء الله- وله أجر، لكن لا ينبغي له ذلك، ينبغي له أن يبدأ بالقضاء؛ لأنه هو الفرض؛ ولأنه أحوط لحقه قد يعوقه عائق، قد يهجم عليه الأجل، فينبغي له أن يبدأ بالقضاء، فالقول بالبداءة بالقضاء أولى وأحوط؛ حيطة للدين، وحرصًا على براءة الذمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13192/وقت-صوم-ست-من-شوال-وحكم-تقديمها-على-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62811.mp3","categories":["صيام التطوع"]},{"id":14702,"question":"ما الحكم في امرأة كانت تصوم الإثنين والخميس، فتركت ذلك الصيام بسبب ضعف بدنها؟","title":"حكم ترك صيام التطوع ممن كان محافظًا عليه","answer":"الجواب: لا حرج في ذلك، صوم الإثنين والخميس مستحب، وليس بفرض، فمن صامه فله أجر، ومن ترك ذلك فلا حرج، وإذا كانت لها عادة تصوم الإثنين والخميس ثم تركت ذلك لضعف أصابها، أو لبعض الأشغال والحاجات التي شغلتها في البيت أو لأسباب أخرى فلا حرج في ذلك. والمقصود: أن صوم الإثنين والخميس نافلة، وهكذا صوم ثلاثة أيام من كل شهر، وهكذا صوم ستة أيام من شوال، كل هذا نافلة مستحب، من صامه فلا بأس، ومن تركه فلا بأس، ومن صام بعض السنين، وترك بعض السنين فلا بأس، الأمر واسع، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13204/حكم-ترك-صيام-التطوع-ممن-كان-محافظا-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62903.mp3","categories":["صيام التطوع"]},{"id":14710,"question":"ما الحكم في امرأة كانت تصوم الإثنين والخميس، فتركت ذلك الصيام بسبب ضعف بدنها؟","title":"حكم ترك صيام التطوع ممن كان محافظًا عليه","answer":"الجواب: لا حرج في ذلك، صوم الإثنين والخميس مستحب، وليس بفرض، فمن صامه فله أجر، ومن ترك ذلك فلا حرج، وإذا كانت لها عادة تصوم الإثنين والخميس ثم تركت ذلك لضعف أصابها، أو لبعض الأشغال والحاجات التي شغلتها في البيت أو لأسباب أخرى فلا حرج في ذلك. والمقصود: أن صوم الإثنين والخميس نافلة، وهكذا صوم ثلاثة أيام من كل شهر، وهكذا صوم ستة أيام من شوال، كل هذا نافلة مستحب، من صامه فلا بأس، ومن تركه فلا بأس، ومن صام بعض السنين، وترك بعض السنين فلا بأس، الأمر واسع، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13204/حكم-ترك-صيام-التطوع-ممن-كان-محافظا-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62903.mp3","categories":["صيام التطوع"]},{"id":14762,"question":"هل يجوز للإنسان أن يصوم نوافل مثل صوم التاسع من ذي الحجة، أو مثل صوم عاشوراء، أو أي نوافل صوم، وهو عليه قضاء من رمضان؟نرجو الإفادة عن هذه الأسئلة. جزاكم الله خيرًا.","title":"حكم تقديم صوم النوافل على صوم القضاء","answer":"الجواب: الأحوط أن يبدأ بالقضاء والفريضة، هذا هو الأحوط، وفي ذلك خلاف بين أهل العلم، منهم من يمنع ذلك ويقول: يجب أن يبدأ بالقضاء، ومنهم من يقول: لا حرج، ومنهم من يقول: إن بدأ بالقضاء فهو أولى وأحوط، وهذا هو أعدل الأقوال الثلاثة، أنه يبدأ بالقضاء على سبيل الاحتياط، ثم تكون النافلة بعد ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13261/حكم-تقديم-صوم-النوافل-على-صوم-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63803.mp3","categories":["صيام التطوع"]},{"id":14770,"question":"إذا أراد المسلم صيام الست من شوال، ولكن لعوارض حلت لم يصم سوى خمسة أيام، فماذا يفعل؟","title":"ما يفعل من صام خمسة أيام من شوال ثم شُغل؟","answer":"الجواب: الحمد لله، له أجرها، والحمد لله، إذا خرج وقت ذهب شوال، ما عاد فيه شيء، نعم، لا تقضى.\nالمقدم: لا تقضى. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13264/ما-يفعل-من-صام-خمسة-ايام-من-شوال-ثم-شغل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49015.mp3","categories":["صيام التطوع"]},{"id":15370,"question":"على بركة الله، نبدأ هذا اللقاء، ونسأل سماحة الشيخ عبدالعزيز عن إفراد صوم يوم السبت، ما حكمه؟جزاكم الله خيرًا.","title":"حكم إفراد يوم السبت بالصيام","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد ورد في ذلك حديث عن النبي ﷺ أنه نهى عن صوم يوم السبت، إلا فيما افترض علينا، وظن بعض إخواننا صحته، والصواب: أنه حديث ضعيف، ليس بصحيح، بل هو مضطرب، كما أوضح ذلك الحافظ ابن حجر -رحمه الله- في البلوغ، وأنكره الإمام مالك وجماعة، والصواب أنه ضعيف مضطرب شاذ، مخالف للأحاديث الصحيحة، فلا يعول عليه. ولا بأس بصوم يوم السبت منفردًا، أو مع الجمعة، ويدل على عدم صحته، ما ثبت في الصحيحين عن النبي ﷺ أنه قال: لا تصوموا يوم الجمعة إلا أن تصوموا يومًا قبله أو يومًا بعده واليوم الذي بعده هو يوم السبت، وثبت عنه ﷺ «أنه كان يصوم يوم السبت والأحد، ويقول: إنهما يوما عيد المشركين؛ فأحب أن أخالفهم. المقصود: أن الحديث الذي فيه النهي عن صوم السبت حديث غير صحيح، بل هو شاذ مخالف للأحاديث الصحيحة، لا يجوز التعويل عليه، ومن صححه من بعض الإخوان فقد غلط؛ ولهذا ثبت عنه ﷺ أنه لما نهى عن صوم يوم الجمعة قال: لا تصوموه إلا أن تصوموا يومًا قبله أو يومًا بعده والذي بعده هو يوم السبت، وكان يصوم يوم السبت -عليه الصلاة والسلام-، ويصوم يوم الأحد، ويقول: إنهما يوما عيد المشركين، وأنا أحب أن أخالفهم -عليه الصلاة والسلام-، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13873/حكم-افراد-يوم-السبت-بالصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56701.mp3","categories":["صيام التطوع"]},{"id":15404,"question":"يقول السائل من الأردن عدنان: زوجتي تصوم بعد شهر رمضان ستة أيام من شهر شوال، زيادة في الأجر والثواب، وبعد ذلك تقضي ما أفطرته في رمضان لعذر شرعي في باقي أشهر السنة، هل يجوز ذلك، أم يجب أن تقضي أولًا؟","title":"حكم صيام الست من شوال قبل قضاء رمضان","answer":"الجواب: الواجب أن تقضي أولًا، ثم تصوم الست؛ لأن الرسول ﷺ قال: من صام رمضان ثم أتبعه ستًا من شوال الست تكون تابعة لرمضان، فالواجب البداءة بالقضاء، ثم تصوم الست بإذنك إذا أذنت لها، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13903/حكم-صيام-الست-من-شوال-قبل-قضاء-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56723.mp3","categories":["صيام التطوع"]},{"id":15702,"question":"هل صيام يوم عرفة مكفر للكبائر؟","title":"هل صيام يوم عرفة يكفر الكبائر؟","answer":"الجواب: ظاهر السنة أنه في الصغائر، يقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان؛ كفارة لما بينهن، إذا اجتنب الكبائر والصلاة أعظم من الحج، الصلاة أعظم من الحج، والنبي ﷺ قال: الحج المبرور ليس له جزاء إلا الجنة وقال ﷺ: من حج فلم يرفث ولم يفسق رجع كيوم ولدته أمه ويقول ﷺ: إن الرب -جل وعلا- يباهي بأهل الموقف الملائكة -موقف عرفة، يباهي بهم- ويدنو، فيقول: ماذا أراد هؤلاء؟ ويقول: ما من يوم أكثر عتيقًا من النار من يوم عرفة يعتق الله من النار، فهم يرجى لهم العتق من النار، ويرجى لهم المغفرة مطلقًا؛ لكن ظاهر الأحاديث أن الحج كغيره يغفر به الصغائر، إلا إذا تاب من الكبائر؛ ولهذا قال: من حج فلم يرفث ولم يفسق والحج من ضمنه الوقوف بعرفة، والذي لم يرفث ولم يفسق هو الذي قد تاب من الذنوب، هو الذي أتى ربه بغير إصرار على الذنوب، فيكون حجه مكفرًا لسيئاته، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14260/هل-صيام-يوم-عرفة-يكفر-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57311.mp3","categories":["صيام التطوع"]},{"id":15703,"question":"سماحة الشيخ، صيام يوم عاشوراء من محرم، إذا صام الشخص يوم عاشوراء من محرم فقط، ولم يصم يومًا قبله، ولا يومًا بعده؛ هل يجزئه ذلك؟","title":"هل يجزئ صيام يوم عاشوراء مفردًا؟","answer":"الجواب: نعم يجزئه؛ لكن ترك الأفضل، الأفضل أن يصوم قبله يومًا، أو بعده يومًا، هذا هو الأفضل، يعني: يصوم يومين، التاسع والعاشر، أو العاشر والحادي عشر، أو يصوم الثلاثة: التاسع، والعاشر، والحادي عشر، هذا أفضل، خلافًا لليهود، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14261/هل-يجزى-صيام-يوم-عاشوراء-مفردا","audio":"","categories":["صيام التطوع"]},{"id":15715,"question":"هل يجوز صيام يوم الجمعة؟","title":"حكم إفراد يوم الجمعة بالصوم","answer":"الجواب: لا يجوز تحريها بالصوم، الرسول ﷺ نهى عن هذا، نهى عن تخصيصها بالصوم، أما إذا كان في صوم الإنسان صام معها السبت، أو صام معها الخميس فلا بأس، أو في صومه في قضاء رمضان، أو في نافلة فلا بأس، أو صامها لأنها يوم عرفة، ما هو لأجل تخصيصها، بل وافقت يوم عرفة فصام، أو لأن عليه قضاء ولم يتيسر له القضاء إلا في يوم الجمعة، لا من أجل يوم الجمعة، لكنه ما تيسر له القضاء إلا فيها، فهذا معذور.","link":"https://binbaz.org.sa/fatwas/14274/حكم-افراد-يوم-الجمعة-بالصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57405.mp3","categories":["صيام التطوع"]},{"id":15833,"question":"من الأردن السائلة خلود عيسى تقول: هل يجوز صيام يوم السبت قضاءً أو نافلة؟","title":"حكم صيام يوم السبت","answer":"الجواب: نعم، لا بأس بصوم يوم السبت قضاءً أو نافلة؛ لأن الحديث الذي فيه النهي عن صوم يوم السبت حديث ضعيف شاذ، مخالف للأحاديث الصحيحة، الذي فيه النهي عن صوم يوم السبت هذا حديث ليس بصحيح، بل هو شاذ عند أهل العلم، وليس بصحيح، فلا حرج أن يصوم الإنسان يوم السبت وحده، أو مع الجمعة، أو مع الأحد، لا بأس، كله طيب، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14422/حكم-صيام-يوم-السبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57525.mp3","categories":["صيام التطوع"]},{"id":16020,"question":"من ليبيا المستمعة فريحة حامد الشريف رسالة وضمنتها جمعًا من الأسئلة، تقول في سؤالها الأول: إذا بدأت الصيام من يوم السبت حتى نهاية الأسبوع، فهل علي أن أتم صيام يوم الجمعة، أم أنني أصوم يوم السبت، وأترك الجمعة؟ جزاكم الله خيرًا.","title":"حكم صيام يوم الجمعة","answer":"الجواب: الأفضل للمؤمن والمؤمنة أن يتحرى الأيام الفاضلة مثل الإثنين والخميس يصومهما، مثل ثلاثة أيام من كل شهر يصومها، وإن سرد أيامًا وأفطر أيامًا فلا بأس، وإذا سرد أيامًا، وصار منها يوم الجمعة؛ فلا حرج، وإذا صام الخميس والجمعة، أو الجمعة والسبت؛ فلا حرج، النهي إنما هو إذا كان خص الجمعة وحدها بتطوع، إذا خصها وحدها، هذا هو محل النهي. أما إذا صامها مع الخميس، أو مع السبت، أو ضمن أيام سردها؛ فلا حرج عليه، لكن الأفضل إذا كان عنده قدرة أن يصوم يومًا، ويفطر يومًا، هذا أفضل الصيام، وهو صيام داود نبي الله -عليه الصلاة والسلام- يقول فيه النبي ﷺ إن هذا أفضل الصيام، أن يصوم يومًا، ويفطر يومًا، وإن صام الإثنين والخميس؛ فهذا خير عظيم، أو صام ثلاثة أيام من كل شهر؛ كفى؛ لأن الحسنة بعشر أمثالها، كل ذلك طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14670/حكم-صيام-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80110.mp3","categories":["صيام التطوع"]},{"id":16030,"question":"من ليبيا المستمعة فريحة حامد الشريف رسالة وضمنتها جمعًا من الأسئلة، تقول في سؤالها الأول: إذا بدأت الصيام من يوم السبت حتى نهاية الأسبوع، فهل علي أن أتم صيام يوم الجمعة، أم أنني أصوم يوم السبت، وأترك الجمعة؟ جزاكم الله خيرًا.","title":"حكم صيام يوم الجمعة","answer":"الجواب: الأفضل للمؤمن والمؤمنة أن يتحرى الأيام الفاضلة مثل الإثنين والخميس يصومهما، مثل ثلاثة أيام من كل شهر يصومها، وإن سرد أيامًا وأفطر أيامًا فلا بأس، وإذا سرد أيامًا، وصار منها يوم الجمعة؛ فلا حرج، وإذا صام الخميس والجمعة، أو الجمعة والسبت؛ فلا حرج، النهي إنما هو إذا كان خص الجمعة وحدها بتطوع، إذا خصها وحدها، هذا هو محل النهي. أما إذا صامها مع الخميس، أو مع السبت، أو ضمن أيام سردها؛ فلا حرج عليه، لكن الأفضل إذا كان عنده قدرة أن يصوم يومًا، ويفطر يومًا، هذا أفضل الصيام، وهو صيام داود نبي الله -عليه الصلاة والسلام- يقول فيه النبي ﷺ إن هذا أفضل الصيام، أن يصوم يومًا، ويفطر يومًا، وإن صام الإثنين والخميس؛ فهذا خير عظيم، أو صام ثلاثة أيام من كل شهر؛ كفى؛ لأن الحسنة بعشر أمثالها، كل ذلك طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14670/حكم-صيام-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80110.mp3","categories":["صيام التطوع"]},{"id":16039,"question":"تقول: لقد جاء يوم عرفة في يوم جمعة، وصمت يوم الجمعة الذي هو يوم عرفة، ولم أصم يوم الخميس، فهل علي إثم؟","title":"حكم صوم الجمعة إذا وافق يوم عرفة","answer":"الجواب: نرجو أن لا إثم عليك؛ لأنك ما قصدت صومه مفردًا، وإنما صمتيه لأجل أنه يوم عرفة فقط، ولكن لو صمت معه الخميس يكون أحوط؛ لأن الرسول ﷺ نهى عن إفراد الجمعة بالصوم في حق المتنفل، فأنت متنفلة، فإذا صمت معه الخميس؛ يكون أحوط، وإن كان قصدك لأجل عرفة، لكن كون المؤمن يتحرى موافقة النبي ﷺ وامتثال ما أمر به أحوط. أما صومه مفردًا لقصد فضله هذا لا يجوز؛ لأن الرسول ﷺ نهى عن ذلك، لكن إذا صامه من أجل أنه يوم عرفة؛ فنرجو أن يكون لا شيء عليه، لكن لو احتاط، وصام معه الخميس؛ يكون أسلم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14677/حكم-صوم-الجمعة-اذا-وافق-يوم-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74808.mp3","categories":["صيام التطوع"]},{"id":16221,"question":"يقول: أرجو ذكر الأيام التي يستحب فيها الصيام، صيام التطوع، جزاكم الله خيرًا.","title":"الأيام التي يستحب فيها الصيام","answer":"الجواب: يستحب للمسلم والمسلمة صيام الإثنين والخميس إذا تيسر ذلك، وإذا كان لها زوج؛ فلابد من رضا الزوج، وستة أيام من شوال في الفطر الأول، ويستحب أيضًا صيام عشر ذي الحجة إذا تيسر ذلك من أولها إلى التاسع لغير الحاج، أما الحاج فلا يصوم التاسع، وهو يوم عرفة.  وإن صام يومًا، وأفطر يومًا فهذا أفضل الصيام، صيام يوم، وفطر يوم، هذا أفضل الصيام، ويستحب صيام ثلاثة أيام من كل شهر، وإذا كانت أيام البيض؛ كان أفضل: يوم الثالث عشر، والرابع عشر، والخامس عشر، هذه أفضل، وإن صامها في غير البيض؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14896/الايام-التي-يستحب-فيها-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75111.mp3","categories":["صيام التطوع"]},{"id":16253,"question":"على بركة الله نبدأ هذا اللقاء برسالة السائلة أم خالد، تقول في سؤالها الأول: سماحة الشيخ! ما حكم إفراد يوم السبت بالصيام، سواءً كان قضاء، أو تطوعًا؟ جزاكم الله خيرًا.","title":"ما حكم إفراد يوم السبت بالصيام، قضاء، أو تطوعًا؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج في إفراد يوم السبت بالصوم، سواء فرضًا، أو تطوعًا، السبت، أو الأحد، أو الإثنين كله لا بأس به إلا الجمعة لا يجوز تخصيصها بصوم التطوع، يوم الجمعة خاصة، الرسول ﷺ نهى أن تخص بالصوم، أما إذا صامها في صوم يصومه، أو عن فريضة، أو يوم عرفة؛ هذا لا بأس، أما أن يخصها بالصوم؛ فلا يجوز، يوم الجمعة خاصة، أما يوم السبت فلا بأس أن يصومه تطوعًا، أو فرضًا. أما الحديث الذي فيه النهي عن صوم يوم السبت فهو حديث مضطرب غير صحيح عند المحققين من أهل العلم، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14929/ما-حكم-افراد-يوم-السبت-بالصيام-قضاء-او-تطوعا","audio":"","categories":["صيام التطوع"]},{"id":16267,"question":"... السائل أخوكم في الله أبو سارة، يقول: أريد أن أسأل يا سماحة الشيخ عن الصائم للتطوع، ثم أراد أن يفطر دون أن يكمل صومه، فهل عليه شيء، وذلك بدون عذر؟","title":"ما حكم الفطر للصائم تطوعًا؟","answer":"الجواب: المتطوع له أن يفطر، أمير نفسه، إن شاء كمل، وإن شاء أفطر، والأفضل الإكمال، فإذا دعت الحاجة إلى أن يفطر؛ فلا بأس. المقصود: أن المتطوع أمير نفسه، إن كمل؛ فهو أفضل، وإن دعت الحاجة إلى إفطاره؛ فلا بأس والحمد لله، كأن يأتيه ضيف يفطر، يأكل مع الضيف، كأن يجد حرًا شديدًا يفطر، أو ما أشبه ذلك من الحاجات التي تدعوه إلى الفطر، لا بأس. المقصود: أنه يجوز له الفطر؛ لأنه نافلة ما هو بفرض، فإذا أفطر، ولو بغير عذر؛ لابأس. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14953/ما-حكم-الفطر-للصاىم-تطوعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58105.mp3","categories":["صيام التطوع"]},{"id":16446,"question":"على بركة الله نبدأ هذا اللقاء برسالة من جدة، السائلة (ن. ف) تقول: سماحة الشيخ! لقد كنت صائمة في يوم الإثنين تطوعًا، ولكن اشتد علي الجوع، وأصابتني بعض الآلام، والتعب الشديد، فقالت لي أختي: أفطري، ولا حرج عليك؛ لأن هذا صوم تطوع، فأفطرت، ولكنني سمعت يا سماحة الشيخ من بعض النساء بأن من أفطر في صوم تطوع، وقد صام بعض اليوم؛ وجب عليه القضاء. فما الحكم مأجورين؟","title":"جواز الفطر في صوم التطوع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد دلت السنة الصحيحة عن رسول الله ﷺ أن المتطوع أمير نفسه، فإذا صام تطوعًاً؛ فله أن يفطر، ولا سيما إذا احتاج إلى ذلك؛ فلا حرج في ذلك. المقصود: أن المتطوع بالصيام له أن يفطر، سواءً في أول النهار، أو في أثناء النهار، وإذا دعت الحاجة إلى ذلك من باب أولى، إذا أحس بشيء من الضعف، أو دعاه صاحب له لوليمة عرس، أو غيره، وأحب أن يجبر خاطره، وأفطر فلا بأس، كل هذا لا حرج فيه، والحمد لله، المتطوع أمير نفسه، إن شاء كمل، وإن شاء أفطر، نعم. المقدم: إذا كان -يا سماحة الشيخ- الإنسان صائمًا صيام قضاء، هل يجوز ... الشيخ: أما القضاء لا، ليس له أن يفطر إلا من مرض، أو سفر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15142/جواز-الفطر-في-صوم-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58201.mp3","categories":["صيام التطوع","قضايا المرأة"]},{"id":16635,"question":"رسالة بعث بها أحد الإخوة المستمعين ضمنها سؤالين، يقول: أنا إنسان أصوم يوم عرفة سنويًّا، وكذلك عاشوراء، ولكن نسيت في العام الماضي يوم عاشوراء، حيث أفطرت في نصف اليوم ناسيًا أنه يوم عاشوراء، لكني أكملت صيامي، وصمت اليوم الحادي عشر، فهل عملي هذا صحيح؟","title":"حكم من اعتاد صيام عاشوراء ثم فاته صيامه ناسيًا","answer":"الجواب: عاشوراء كله صومه طيب، فإذا صمت منه ما تيسر فالحمد لله، ونرجو لك الأجر في اليوم الذي فاتك بسبب النسيان؛ لأنك تركته غير عامد، بل ناس، فلك أجره -إن شاء الله- وصومك الحادي عشر طيب؛ لأن اليوم العاشر فاتك نسيانًا؛ فلك أجره، كما لو تركته مريضًا، ثم طبت في اليوم الحادي عشر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15366/حكم-من-اعتاد-صيام-عاشوراء-ثم-فاته-صيامه-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71612.mp3","categories":["صيام التطوع"]},{"id":16726,"question":"من الأردن هذا السائل أرسل بمجموعة من الأسئلة، يقول يا سماحة الشيخ: إذا صادف يوم عاشوراء يوم السبت فهل يجوز لنا أن نصومه؟","title":"جواز صوم يوم السبت مطلقًا","answer":"الجواب: لا حرج أن يصوم الإنسان يوم السبت مطلقًا في الفرض والنفل، والحديث الذي فيه النهي عن صوم السبت حديث ضعيف مضطرب شاذ، مخالف للأحاديث الصحيحة، فلا بأس أن يصوم المسلم يوم السبت، سواءٌ كان عن فرض، أو عن نفل، ولو ما صام معه غيره، والحديث الذي فيه النهي عن صوم يوم السبت إلا في فرض حديث غير صحيح، بل هو ضعيف، وشاذ، مخالف للأحاديث الصحيحة، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15475/جواز-صوم-يوم-السبت-مطلقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58428.mp3","categories":["صيام التطوع"]},{"id":16727,"question":"من أسئلة هذا السائل من الأردن يقول يا سماحة الشيخ: إذا أردنا أن نصوم ستة أيام من شوال بشكل تتابعي، وصادف في أحد الأيام يوم السبت فهل نصوم ذلك، أم نفطر؟","title":"حكم صيام يوم السبت إذا وافق ستًا من شوال","answer":"الجواب: مثلما تقدم، الأفضل أن يصومه متتابعة، وصوم يوم السبت لا بأس به، ولو مفردًا؛ لأن الحديث الذي فيه النهي عن صوم يوم السبت إلا فيما افترض علينا حديث ضعيف -كما تقدم- لا يصح عن النبي ﷺ.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15479/حكم-صيام-يوم-السبت-اذا-وافق-ستا-من-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58429.mp3","categories":["صيام التطوع"]},{"id":16848,"question":"إذا أفطرت صيام الستة الأيام من شوال، ثم أردت أن أصومها في نفس الشهر، فمتى يبدأ، هل هناك تاريخ معين؟","title":"وقت صيام الست من شوال","answer":"الجواب: كل شوال محل صوم، والأفضل البدار، الأفضل البدار بها قبل العوائق، سواء متتابعة، أو مفرقة، وإن صامها في آخر الشهر، أو في وسطه؛ فلا بأس، الأمر واسع، النبي  قال: من صام رمضان، ثم أتبعه ستًا من شوال؛ كان كصيام الدهر ولم يحدد أوله، ولا وسطه، ولا آخره -عليه الصلاة والسلام- لكن البدار أفضل؛ لقول الله  عن موسى: وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَى [طه:84]، ولقوله سبحانه: وَسَارِعُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ [آل عمران:133] قوله -جل وعلا-: فَاسْتَبِقُوا الْخَيْرَاتِ [البقرة:148]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15599/وقت-صيام-الست-من-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76405.mp3","categories":["صيام التطوع"]},{"id":16926,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من ليبيا، بعث بها أحد الإخوة المستمعين من هناك، عرضنا بعضًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل عن صيام الست من شوال وعن فضلها؟ جزاكم الله خيرًا.","title":"فضل صيام الست من شوال","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من صام رمضان، ثم أتبعه ستًا من شوال؛ كان كصيام الدهر رواه مسلم في صحيحه، وهذا يدل على فضلها، وأن صيام الست مع رمضان كصيام الدهر، كأنه صام الدهر كله، وهذا فضل عظيم، فرمضان بعشرة أشهر، والست بشهرين، الحسنة بعشر أمثالها، فكأنه صام الدهر كله، مع أن الله بلطفه -جل وعلا- جعل رمضان كفارة لما بين الرمضانين، فالست فيها زيادة خير، ومصلحة عظيمة، وفائدة كبيرة في امتثال أمر النبي ﷺ امتثال إرشاد النبي ﷺ وترغيبه، والحرص على فعل ما شرع الله من العبادة، وهذا خير عظيم، والمؤمن يتحرى ما شرع الله، ويمتثل يطلب الثواب من الله، هذا له فيه أجر عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15699/فضل-صيام-الست-من-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82614.mp3","categories":["صيام التطوع"]},{"id":17027,"question":"رسالةٌ وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها جمعًا من الأسئلة، في أحدها يقول: ما حكم صيام يوم النصف من شعبان، وقيام ليلة النصف من شعبان، والدعاء الذي يقال في هذه الليلة؟","title":"حكم صيام يوم النصف من شعبان وقيام ليلته","answer":"الجواب: هذا ضعيفٌ، ليس له أصلٌ، ليس له أصلٌ صحيحٌ، فلا يُستحب صيام يوم النصف، ولا يُستحب قيام ليلة النصف؛ لعدم ثبوت الأحاديث في ذلك، وقد كتبنا في هذا عدة كتاباتٍ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15810/حكم-صيام-يوم-النصف-من-شعبان-وقيام-ليلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83005.mp3","categories":["البدع والمحدثات","صيام التطوع"]},{"id":17314,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم في الله (ف. ح. م) المطيري أختنا لها جمع من الأسئلة في أحدها تقول: من أراد صوم يوم الإثنين والخميس هل يجب عليه صومهما دائمًا، أم حسب الاستطاعة؟","title":"حكم المداومة على صيام الإثنين والخميس","answer":"الجواب: لا يجب عليك دائمًا، بل هذا مستحب متى تيسر ذلك، النافلة لا تجب أبدًا إلا بالنذر، فإذا صام الإثنين والخميس هذا عمل طيب، والرسول ﷺ كان يصومهما -عليه الصلاة والسلام- ويقول: إنهما يومان تعرض فيهما الأعمال على الله، فأحب أن يعرض عملي وأنا صائم ومن أفطر فلا حرج، أو صام بعض الأيام، وترك بعض الأيام، صام بعض الشهور، وترك بعض الشهور، صام في بعض الأسابيع، وترك بعض الأسابيع، لا بأس، الأمر واسع -بحمد الله- لأنها نافلة.  وهكذا لو كان يصوم الست من شوال إذا تركها بعض السنين فلا بأس، لكن الأفضل المداومة، إذا تيسرت المداومة فهي أفضل، يقول النبي ﷺ: أحب الأعمال إلى الله ما دام عليه صاحبه، وإن قل وهكذا صوم يوم عرفة سنة لغير الحجاج، أما الحاج فلا يصوم يوم عرفة، لكن غير الحجاج السنة أن يصوموا يوم عرفة، ولو أفطر في بعض السنوات لا حرج، وهذه قاعدة: النافلة لا تلزم إلا بالنذر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16187/حكم-المداومة-على-صيام-الاثنين-والخميس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83316.mp3","categories":["صيام التطوع"]},{"id":17352,"question":"تقول: إنني سمعت أن من صام يوم السبت لا يصح صومه إلا مع صوم يوم قبله، أو بعده، وإنني صمت يوم السبت قضاء كفارة يمين، ولم أصم يوم الأحد؛ لأنني لم أستيقظ من النوم إلا بعد الأذان فهل يجب علي إعادة الصوم، بينوا حكم ذلك، بارك الله فيكم؟","title":"حكم صيام يوم السبت مفردًا","answer":"الجواب: الصوم صحيح، صوم يوم السبت صحيح، ولو مفردًا، والحديث الذي فيه النهي عن صوم يوم السبت حديث ضعيف، مضطرب عند أهل العلم، لا يعتمد عليه، لكن لو صمت السبت مع الأحد، أو مع الجمعة كان أفضل، وإلا فالصوم ليوم السبت مفردًا الصحيح أنه لا حرج فيه، وأن الحديث فيه ضعيف لاضطرابه، وعدم استقامة أسانيده، ولكن من باب الورع، والخروج من الخلاف إذا صام الإنسان يوم السبت يصم معه الأحد، أو الجمعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16201/حكم-صيام-يوم-السبت-مفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83403.mp3","categories":["صيام التطوع"]},{"id":17564,"question":"في آخر أسئلة هذه السائلة من اليمن تقول: هل يجوز صوم الست من شوال قبل القضاء؟","title":"حكم صيام الست من شوال قبل القضاء","answer":"الجواب: الواجب تقديم القضاء؛ لأن القضاء أهم، والرسول ﷺ قال..: من صام رمضان ثم أتبعه ستًا من شوال، فاللي صامت الست قبل تمام رمضان ما أتبعته، لا بد تبدأ، والرجل يبدأ بقضاء رمضان ثم يصوم الست. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16486/حكم-صيام-الست-من-شوال-قبل-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77522.mp3","categories":["صيام التطوع","قضايا المرأة"]},{"id":17831,"question":"السائل الأخ المستمع أبو خالد من مكة المكرمة يسأل ويقول: هل يجوز صيام آخر يوم من شهر شعبان؟","title":"حكم صيام آخر يوم من شعبان","answer":"الجواب: إذا كان لك عادة تصوم الإثنين والخميس وصادف آخر يوم الإثنين أو الخميس تصومه، لقوله ﷺ: لا تقدموا رمضان بصوم يوم ولا يومين، إلا رجل كان يصوم صومًا فليصمه. اللي له عادة يصوم يوم ويفطر يوم، أو يصوم الإثنين والخميس، وصادف يوم الصيام يوم الثلاثين من شعبان يصومه؛ لأنه يصومه كعادته، أما يتطوع به لأجل رمضان لا. ينهى عن هذا.","link":"https://binbaz.org.sa/fatwas/16823/حكم-صيام-اخر-يوم-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59728.mp3","categories":["صيام التطوع"]},{"id":17937,"question":"ما هو صوم التطوع؟ وكم يوم في الأسبوع؟","title":"ما هو صيام التطوع وما يشرع صيامه؟","answer":"الجواب: كل ما كان غير الفريضة يسمى تطوعًا، الصوم الذي ليس عن رمضان ولا عن كفارة ولا عن نذر هذا يسمى تطوعًا مثل صيام الإثنين والخميس، صيام أيام البيض الثلاث عشر والرابع عشر والخامس عشر، مثل صيام يوم وفطر يوم، صيام ست من شوال، صيام عاشوراء، صيام عرفة لغير الحجاج، كل هذا يسمى نوافل.. نافلة.\nالشيخ: أعد سؤاله.\nالمقدم: يقول: ما هو صوم التطوع؟ وكم يوم في الأسبوع؟\nالشيخ: كل ما عدا الفرائض فهو تطوع، والأفضل الإثنين والخميس، وإن صام يومًا وأفطر يومًا فهو أفضل، الصيام كما أخبر النبي ﷺ بذلك لـعبد الله بن عمرو قال: صم يومًا وأفطر يومًا، فذلك أفضل الصيام وهو صوم داود عليه الصلاة والسلام ولكن ليس بلازم إنما هو مستحب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16961/ما-هو-صيام-التطوع-وما-يشرع-صيامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84708.mp3","categories":["صيام التطوع"]},{"id":17943,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول في نهاية رسالتها: أختكم في الله أم أنس من مدينة تبوك، أختنا تسأل جمعًا من الأسئلة في أحدها تقول: لقد سمعت بأن التي تريد صيام ستة أيام من شوال تطوعًا وكذلك الأيام البيض الثلاثة عشر والأربعة عشر والخمسة عشر بأنه يجب عليها المداومة في ذلك، فهل ما قيل صحيح؟","title":"هل يجب المداومة على صيام النفل؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفصيام الأيام الستة من شوال وهكذا أيام البيض وهكذا يوم الإثنين والخميس كلها سنة كلها مستحبة نوافل من صامها وداوم عليها فله أجره، ومن صامها تارة وتركها تارة فله أجره، ولا تجب، ما تجب المداومة، والذي يقول: إنه تجب المداومة قد غلط، بل ذلك إلى المسلم متى تيسر له صام، ومتى شغل عن ذلك أفطر، والنبي ﷺ كان ربما صام وسرد الصوم حتى يقال: لا يفطر، وربما سرد الإفطار حتى يقال: لا يصوم، بسبب مراعاته المشاغل وعدم وجود المشاغل، فإذا فرغ سرد الصوم، وإذا شغل سرد الفطر عليه الصلاة والسلام.\nوالخلاصة: أنه لا يجب على المؤمن أن يداوم على الست أو أيام البيض، بل متى تيسر له صامها وإذا تركها فلا حرج، والحمد لله، وهكذا إذا كان يصوم الإثنين والخميس إذا تركها بعض الأحيان لا حرج كلها نافلة والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16947/هل-يجب-المداومة-على-صيام-النفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84701.mp3","categories":["صيام التطوع"]},{"id":17945,"question":"ما هو صوم التطوع؟ وكم يوم في الأسبوع؟","title":"ما هو صيام التطوع وما يشرع صيامه؟","answer":"الجواب: كل ما كان غير الفريضة يسمى تطوعًا، الصوم الذي ليس عن رمضان ولا عن كفارة ولا عن نذر هذا يسمى تطوعًا مثل صيام الإثنين والخميس، صيام أيام البيض الثلاث عشر والرابع عشر والخامس عشر، مثل صيام يوم وفطر يوم، صيام ست من شوال، صيام عاشوراء، صيام عرفة لغير الحجاج، كل هذا يسمى نوافل.. نافلة.\nالشيخ: أعد سؤاله.\nالمقدم: يقول: ما هو صوم التطوع؟ وكم يوم في الأسبوع؟\nالشيخ: كل ما عدا الفرائض فهو تطوع، والأفضل الإثنين والخميس، وإن صام يومًا وأفطر يومًا فهو أفضل، الصيام كما أخبر النبي ﷺ بذلك لـعبد الله بن عمرو قال: صم يومًا وأفطر يومًا، فذلك أفضل الصيام وهو صوم داود عليه الصلاة والسلام ولكن ليس بلازم إنما هو مستحب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16961/ما-هو-صيام-التطوع-وما-يشرع-صيامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84708.mp3","categories":["صيام التطوع"]},{"id":18056,"question":"أيهما أفضل؛ صيام الأيام البيض، أم الإثنين والخميس؟","title":"أفضلية صيام الإثنين والخميس على أيام البيض","answer":"الجواب: كلها فاضلة، لكن صيام الإثنين والخميس أكثر أجرًا؛ لأن أيام الإثنين والخميس أيامٌ كثيرة في الشهر، أما الأيام البيض ثلاثة أيام فقط، فإذا صام الإثنين والخميس حصل له صيام ثلاثة أيام من كل شهر، وحصل له الزيادة، هذا أفضل، وأكثر، وإن جمع بينها، صام البيض، وصام الإثنين والخميس؛ كله خير، كله طيب. المقدم: وربما تصادف الأيام البيض الإثنين، أو الخميس؟ الشيخ: قد تصادف نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17088/افضلية-صيام-الاثنين-والخميس-على-ايام-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72913.mp3","categories":["صيام التطوع"]},{"id":18094,"question":"رسالة وصلت إلى البرنامج من جدة، وباعثتها إحدى الأخوات، تقول: من أختكم في الله ( م. م مايدة )، أختنا تقول: ما هي الأيام البيض؟ جزاكم الله خيرًا.","title":"المقصود بالأيام البيض","answer":"الجواب: الأيام البيض هي: الثالث عشر، والرابع عشر، والخامس عشر، هذه هي البيض، يعني: التي ليلها أبيض بالقمر، ونهارها أبيض بالشمس والنهار، صيامها مستحب، وإن صام في غيرها فلا بأس، السنة أن يصوم المسلم من كل شهر ثلاثة أيام، وهكذا المسلمة، الرسول ﷺ أوصى بصيام ثلاثة أيام من كل شهر، أوصى جماعة من الصحابة، فإذا صامها في العشر الأول، أو في الوسطى، أو في الأخيرة، فكله طيب، وإن صامها في أيام البيض، فهو أفضل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17129/المقصود-بالايام-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73018.mp3","categories":["صيام التطوع"]},{"id":18212,"question":"متى يبدأ صيام شهر المحرم أو صيام عاشوراء هل يبدأ في أول محرم أو في وسطه أو في آخره، وكم عدد صيامه؛ لأنني سمعت أن صيام عاشوراء يبدأ من واحد محرم إلى عشرة محرم؟ وفقكم الله.","title":"متى يصام يوم عاشوراء؟","answer":"الجواب: يقول النبي ﷺ: أفضل الصيام بعد رمضان شهر الله المحرم وهو عاشوراء، والمعنى: أنه يصومه كله من أوله إلى آخره من أول يوم منه إلى نهايته، هذا معنى الحديث، ولكن يخص منه يوم التاسع والعاشر أو العاشر والحادي عشر لمن لم يصمه كله؛ فإن النبي ﷺ كان يصوم عاشوراء في الجاهلية وكانت تصومه قريش أيضًا، فلما قدم المدينة عليه الصلاة والسلام وجد اليهود يصومونه، فسألهم عن ذلك فقالوا: إنه يوم نجى الله فيه موسى وقومه، وأهلك فرعون وقومه، فصامه شكرًا لله صامه موسى شكرًا لله ونحن نصومه، فقال النبي ﷺ: نحن أحق وأولى بـموسى منكم فصامه وأمر بصيامه فالسنة أن يصام هذا اليوم يوم عاشوراء. والسنة أن يصام قبله يوم أو بعده يوم؛ لما روي عنه عليه الصلاة والسلام أنه قال: صوموا يومًا قبله ويومًا بعده ، وفي لفظ: يومًا قبله أو يومًا بعده. وفي حديث آخر: لأن عشت إلى قابل لأصومن التاسع يعني: مع العاشر، فهذا هو الأفضل، أن يصام العاشر؛ لأنه يوم عظيم حصل فيه الخير العظيم لـموسى والمسلمين، وصامه نبينا محمد عليه الصلاة والسلام فنحن نصومه تأسيًا بنبينا عليه الصلاة والسلام وعملًا بما شرع عليه الصلاة والسلام، ونصوم معه يومًا قبله أو يومًا بعده مخالفة لليهود. والأفضل التاسع مع العاشر لحديث: لأن عشت إلى قابل لأصومن التاسع فإن صام العاشر والحادي عشر أو صام الثلاثة فكله حسن، فإن صام التاسع والعاشر والحادي عشر كله طيب، وفيه مخالفة لليهود، فإن صام الشهر كله فهو أفضل وأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/17253/متى-يصام-يوم-عاشوراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_856/nour_85602.mp3","categories":["صيام التطوع"]},{"id":18216,"question":"المستمع بهاء أحمد محمد أحمد، بعث يسأل ويقول: أعرفكم أنني شرعت في صيام ثلاثة أيامٍ من كل شهر، وصيام الإثنين والخميس، إلا أنني أشعر بعض الأحيان بالتعب، فهل أكون آثمًا إذا أفطرت؟ جزاكم الله خيرًا.","title":"حكم ترك صيام التطوع لمن اعتاده","answer":"الجواب: لا حرج عليك، إن صمت طيب، وإذا أفطرت بعض الأحيان لا حرج الحمد لله، الأمر واسع، الحمد لله. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17260/حكم-ترك-صيام-التطوع-لمن-اعتاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73121.mp3","categories":["صيام التطوع"]},{"id":18231,"question":"هل صيام يومي الإثنين والخميس من كل أسبوع أو في كل شهر، هل إذا صمتها مرة وجبت علي دائمًا؟","title":"هل صيام النافلة مرة واحدة يوجب المداومة عليها؟","answer":"الجواب: صيام الإثنين والخميس قربة إلى الله، وهو من أفضل العبادات، وكان النبي ﷺ يصومهما، ويقول: إنهما يومان تعرض فيهما الأعمال على الله فأحب أن يعرض عملي وأنا صائم، لكن من صامهما لا يلزمه أن يستمر في ذلك إذا شاء صام وإذا شاء ترك لأنها نافلة، فإن صامهما ثم تركهما بعض الأحيان فلا حرج عليه، أو تركها دائمًا فلا حرج عليه، لكن إذا تيسر له الاستمرار فهذا أفضل، لقوله ﷺ: إن أحب العمل إلى الله ما دام عليه صاحبه وإن قل كون المؤمن يستقيم على العمل الصالح ويستمر عليه هذا أفضل؛ لأنه في حاجة إلى ذلك وينفعه هذا في الدنيا والآخرة. هكذا صلاة الضحى، هكذا التهجد بالليل، هكذا الصلوات المشروعة قبل الفرائض وبعدها كلها نوافل، من حافظ عليها فله أجر عظيم ومن تركها في بعض الأحيان فلا شيء عليه، وهكذا صيام ثلاثة أيام من كل شهر، هكذا صيام يوم عرفة، وصوم يوم عاشوراء، صوم يوم قبله أو بعده كل هذه سنن ونوافل من فعلها فقد أحسن وله أجر عظيم، ومن ترك فلا حرج عليه، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/17277/هل-صيام-النافلة-مرة-واحدة-يوجب-المداومة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85705.mp3","categories":["صيام التطوع"]},{"id":18307,"question":"تقول أختنا: أنا في بعض الأحيان لا أصوم الثلاثة الأيام البيض لعذرٍ شرعي، أو لظروفٍ تحصل لي، فأقوم بصيامها من أول الشهر، أو من آخر الشهر. هل ثواب هذا الصيام مثل ثواب من صام الأيام البيض؟ وجهوني، جزاكم الله خيرًا.","title":"استحباب صيام ثلاثة أيام من كل شهر","answer":"الجواب: صيام الثلاثة مستحب، في أول الشهر، أو في وسطه، أو في آخره، في الأحاديث الصحيحة الكثيرة أوصى النبي ﷺ بصيام ثلاثة أيام من كل شهر، ولم يبين محلها من أوله، أو وسطه، أو آخره، هكذا جاء في الأحاديث الصحيحة، وأوصى أبا هريرة، وأبا الدرداء، وغيرهما، أوصاهما بصيام ثلاثة أيام من كل شهر، وأوصى عبد الله بن عمرو بذلك، لكن جاء في بعض الأحاديث الوصية بأيام البيض وهي الثالث عشر، والرابع عشر، والخامس عشر. فصيام الأيام البيض إذا تيسرت أفضل، وإلا فيصوم الإنسان في بقية الشهر، والحمد لله، وكلها أيام عظيمة وفاضلة، فيها أجر عظيم، لكن صوم أيام البيض أفضل إذا تيسر، إذا تيسر ذلك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17356/استحباب-صيام-ثلاثة-ايام-من-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73204.mp3","categories":["صيام التطوع"]},{"id":18883,"question":"كثير من الناس يصومون الخامس عشر من شعبان، فهل هذا وارد في السنة أم أنه بدعة؟جزاكم الله خيرًا.","title":"حكم تخصيص صيام النصف من شعبان","answer":"الجواب: ليس له أصل، كونه يخص اليوم الخامس عشر ليس له أصل، وليس في السنة الصحيحة ما يدل على ذلك، لكن إذا صام أيام البيض الثالث عشر والرابع عشر والخامس عشر هذا مستحب في جميع الشهور، وكان النبي ﷺ يصوم أيام البيض، ويصوم شعبان كله، وربما صام أكثره، تارة يصوم أكثره وتارة يصومه كله شعبان -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18023/حكم-تخصيص-صيام-النصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73616.mp3","categories":["صيام التطوع"]},{"id":18938,"question":"أختنا تسأل -سماحة الشيخ- وتقول: أنا أصوم الأحد والإثنين، ثم الأربعاء والخميس، وهكذا على هذا الحال حبًا للتطوع، وحبًا للتقليل من الأكل، وخوفًا من السمنة، فما الحكم؟","title":"حكم الصيام بنية التطوع والتخفيف من السمنة","answer":"الجواب: لا بأس، الحمد لله خير هذا، وإذا اقتصرت على الإثنين والخميس، أو ثلاثة أيام من كل شهر، هذا كله طيب، ومن صام ما شاء من الدهر فلا بأس، لكن لا يزيد على أن يصوم يومًا، ويفطر يومًا، قال النبي ﷺ لـعبد الله بن عمرو: صم يومًا، وأفطر يومًا قال: إني أريد أفضل من ذلك، قال -عليه الصلاة والسلام-: لا أفضل من ذلك، هذا صوم داود، نصف الدهر أفضل صيام المتطوع أن يصوم يومًا، ويفطر يومًا إذا قدر واستطاع ذلك، هذا الأفضل، وإذا اكتفى بيوم الإثنين والخميس، أو بثلاثة أيام من كل شهر كان هذا أرفق به، وأفضل، نعم، أفضل له حتى لا يندم، حتى لا يرجع عن عمله. أما أفضل الصيام من حيث هو تطوع فأفضله أن يصوم يومًا، ويفطر يومًا إذا استطاع ذلك، ولم يترتب عليه إخلال بشؤون أهله، ولا إخلال بطلبه العلم، ولا إخلال بواجبات أخرى، فلا بأس، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18088/حكم-الصيام-بنية-التطوع-والتخفيف-من-السمنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92407.mp3","categories":["صيام التطوع"]},{"id":19409,"question":"ننتقل إلى رسالة وصلت من الرياض وباعثتها إحدى الأخوات المستمعات هي (ب.ع) أختنا لها عدد من الأسئلة، ولها مقدمة طويلة بلغت صفحة من رسالتها، كلها ثناء وتقدير على أصحاب الفضيلة المشاركين في هذا البرنامج، وسردت أسئلتها البالغة أكثر من ثمانية أسئلة، فتسأل في سؤالها الأول وتقول: هل صحيح يجوز قضاء الأيام البيض بحيث يبدأ الإنسان بصيامها، ثم يحبسه حابس ويقطعه عن صيامها؟","title":"حكم قضاء صيام الأيام البيض","answer":"الجواب: المشروع للمؤمن والمؤمنة صيام ثلاثة أيام من كل شهر، فإذا صامها أيام البيض فهو أفضل وإن صامها في بقية الشهر كله طيب، النبي ﷺ أوصى بصيام ثلاثة أيام من كل شهر وبين أن أيام البيض أفضل من غيرها، فإذا كانت المرأة أو الرجل يصومون أيام البيض ثم شغلوا عنها يصومون من بقية الشهر والحمد لله ما يسمى قضاء يسمى صيام الثلاثة؛ لأن الشهر كله محل صيام من أوله إلى آخره، فإذا صام المؤمن أو المؤمنة من أوله أو من وسطه أو من آخره الثلاثة حصل المقصود، وحصلت السنية، وإن لم يصمها في أيام البيض. المقدم: جزاكم الله خيرًا، تقصد هل تقضيها إذا فات صيامها؟ الشيخ: ما يسمى قضاء تصوم ثلاثة أيام من كل شهر، المشروع لها أن تصوم ثلاثة أيام من كل شهر سواء وافقت أيام البيض أو لم توافق أيام البيض. المقدم: أيوه، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18634/حكم-قضاء-صيام-الايام-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93604.mp3","categories":["صيام التطوع"]},{"id":19535,"question":"يقول السائل من الجزائر، هل يجوز الصيام في أواخر أيام شهر شعبان، كصيام أيام القضاء أو الكفارة اليمين أو صيام النذر؟","title":"حكم الصيام بعد انتصاف شعبان","answer":"الجواب: الذي عليه صيام يقضيه ولو في آخر شعبان، أما التطوع لا، بعد النص من شعبان لا يتطوع، أما إذا كان عليه قضاء يبادر بالقضاء في شعبان، أو في رجب، أو قبل ذلك، وإذا لم يتيسر إلا في آخر شعبان قضى ما عليه والحمد لله، لكن لا يتطوع بشيء في آخر شعبان؛ لأن الرسول ﷺ قال: إذا انتصف شعبان فلا تصوموا؛ لأن بعض الناس قد يصوم احتياطًا لرمضان فلا يجوز، أما إذا كان عليه قضاء فإن الواجب عليه البدار به، فإن تأخر إلى آخر شعبان وجب عليه القضاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18793/حكم-الصيام-بعد-انتصاف-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94624.mp3","categories":["صيام التطوع"]},{"id":19610,"question":"هذا السائل (إبراهيم . م. م) يقول: والدتي تمنعني من صيام التطوع، وتقول لي: لقد صمت كثيرًا وفيه الكفاية، فهل أصوم أم أترك صيام التطوع، مع العلم بأن جسمي ضعيف ولا أستطيع؟","title":"حكم طاعة الأم في ترك صيام التطوع","answer":"الجواب: عليك طاعة والدتك، عليك أن تطيع الوالدة؛ فإنها بارة بك، ومحسنة فيك، حريصة عليك، فعليك السمع والطاعة فيما تقول لك الوالدة في صوم النافلة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18878/حكم-طاعة-الام-في-ترك-صيام-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94812.mp3","categories":["صيام التطوع"]},{"id":19622,"question":"تقول السائلة من فلسطين: سماحة الشيخ، هل ورد عن النبي ﷺ أنه كان يكثر من الصيام في شهري شعبان ومحرم؟ وهل الأعمال ترفع إلى الله  في شهر شعبان؟","title":"مشروعية الإكثار من الصيام في شعبان ومحرم","answer":"الجواب: كان يصوم شعبان، يصوم أكثره كما أخبرت عائشة رضي الله عنها، كان يصومه إلا قليلاً، وجاء في رواية أم سلمة أنه ربما صامه كله شعبان. ويقول: أفضل الصيام بعد رمضان شهر الله المحرم، كان يصوم عاشوراء وهو يوم العاشر من عاشوراء، وقال في آخر حياته: لئن أدركت عام القابل لأصومن التاسع، والعاشر يعني: التاسع مع العاشر. فالسنَّة صيام عاشوراء قبله يوم أو بعده يوم، التاسع والعاشر، أو العاشر والحادي عشر؛ خلافًا لليهود لقوله ﷺ: أفضل الصيام بعد رمضان شهر الله المحرم فإذا صام التاسع، والعاشر، والحادي عشر خلال ثلاثة أيام هذا طيب حسن. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18893/مشروعية-الاكثار-من-الصيام-في-شعبان-ومحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94824.mp3","categories":["صيام التطوع"]},{"id":19660,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: بأنه يصوم ثلاثة أيام من كل شهر والحمد لله، أحيانًا يصوم في الرابع عشر والخامس عشر والسادس عشر من الشهر، وأحيانًا يصوم أيامًا متفرقة دون تقيد بتاريخ معين، حسب الظروف، فهل عليه شيء في ذلك؟","title":"ما حكم صيام أي ثلاثة أيام من كل شهر؟","answer":"الجواب: كله طيب، لا، كله طيب إن شاء صام أيام البيض، وإن شاء صامها مفرقة في بقية الشهر، في وسطه أو في أوله أو في آخره، النبي ﷺ قال: لـعبد الله بن عمرو: صم من الشهر ثلاثة أيام قال أبو هريرة: أوصاني رسول الله بصيام ثلاثة أيام من كل شهر، سواء من أوله أو من وسطه أو من آخره، وإن صامها أيام البيض الثالث عشر والرابع عشر والخامس عشر فهو أفضل إذا تيسر ذلك. نعم. المقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18949/ما-حكم-صيام-اي-ثلاثة-ايام-من-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95014.mp3","categories":["صيام التطوع"]},{"id":19679,"question":"من أسئلة السائل من الجزائر يقول: يا سماحة الشيخ نهينا عن صيام يوم السبت إلا فيما افترض علينا، فهل بالنسبة لصيام قضاء الدين كالمريض أو المرأة الحائض يصام يوم السبت أثناء فترة القضاء، أم تتجنب صيام ذلك اليوم؟","title":"حكم إفراد يوم السبت بصيام","answer":"الجواب: الحديث ضعيف الذي فيه النهي عن صوم يوم السبت إلا فيما افترض علينا حديث شاذ ضعيف مضطرب فلا حرج في صوم يوم السبت مع الجمعة أو مع الأحد أو وحده لا حرج في ذلك، والحديث المذكور ضعيف لا يصح عن النبي ﷺ كما نبه عليه الحفاظ. نعم. المقدم: جزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18971/حكم-افراد-يوم-السبت-بصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95032.mp3","categories":["صيام التطوع"]}]
